    # ════════════════════════════════════════════════════════════════
    # UI
    # ════════════════════════════════════════════════════════════════

    def _build_ui(self):
        # ── 主体区（Notebook分页）──
        self._body_frame = tk.Frame(self, bg=BG)
        self._body_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=8)

        self._notebook = ttk.Notebook(self._body_frame)
        self._notebook.pack(fill=tk.BOTH, expand=True)

        # === 页签1: 文件阅读 ===
        self._tab_reader = tk.Frame(self._notebook, bg=BG)
        self._notebook.add(self._tab_reader, text="📂 文件阅读")
        self._build_pdf_reader_tab()

        # === 页签2: PDF差异对比 ===
        self._tab_pdf_diff = tk.Frame(self._notebook, bg=BG)
        self._notebook.add(self._tab_pdf_diff, text="🔍 PDF差异对比")
        self._build_pdf_diff_tab()

        # === 页签3: Excel 搜索 ===
        self._tab_excel_search = tk.Frame(self._notebook, bg=BG)
        self._notebook.add(self._tab_excel_search, text="📊 Excel 搜索")
        self._build_excel_search_tab(self._tab_excel_search)

        # ── 页签文字配色 ──
        tab_colors = {
            self._tab_reader:       "#e0a83e",  # 琥珀金 — 文件阅读
            self._tab_pdf_diff:     "#e0607a",  # 玫红色 — PDF差异对比
            self._tab_excel_search: "#4cc38a",  # 翠绿色 — Excel 搜索
        }
        for tab_widget, color in tab_colors.items():
            try:
                tab_id = str(tab_widget)
                self._notebook.tk.call(
                    self._notebook._w, "tab", tab_id, "-foreground", color)
            except Exception:
                pass

        # === 配置持久化 ===
        self._shortcut_bindings = {}
        self._config_file = os.path.join(os.path.dirname(__file__), "config.json")
        self._load_config()
        # 默认选中「文件阅读」页签
        self.after_idle(lambda: self._notebook.select(self._tab_reader))

        # ── 同步已加载的配置到按钮状态 ──
        self._apply_reader_settings_to_ui()
        self._reader_refresh_bookmark_list()

        # === 应用内快捷键（翻页/缩放/聚焦搜索）===
        self._setup_keyboard_shortcuts()
    def _toggle_top_toolbar(self):
        """折叠/展开最上面那条全局工具栏，腾出更多阅读/操作空间。"""
        if self._top_bar_frame.winfo_ismapped():
            self._top_bar_frame.pack_forget()
            self._toolbar_collapse_btn.config(text="▼ 显示工具栏")
        else:
            self._top_bar_frame.pack(fill=tk.X, before=self._toolbar_handle_frame)
            self._toolbar_collapse_btn.config(text="▲ 隐藏工具栏")

    def _toggle_reader_maximize(self):
        """切换阅读窗口最大化：隐藏工具栏和其他页签，只保留阅读区域。"""
        if not self._reader_maximized:
            # ── 进入最大化 ──
            self._reader_max_restore_geo = self.geometry()
            self._reader_maximized = True

            # 隐藏顶部工具栏
            if self._top_bar_frame.winfo_ismapped():
                self._top_bar_frame.pack_forget()

            # 隐藏工具栏手柄（折叠按钮、番茄钟、激励语）
            if self._toolbar_handle_frame.winfo_ismapped():
                self._toolbar_handle_frame.pack_forget()

            # 去掉 body 边距，让阅读区域填满窗口
            self._body_frame.pack_forget()
            self._body_frame.pack(fill=tk.BOTH, expand=True, padx=0, pady=0)

            # 隐藏除"文件阅读"外的所有页签
            reader_tab_id = str(self._tab_reader)
            for tab_id in self._notebook.tabs():
                if tab_id != reader_tab_id:
                    try:
                        self._notebook.tab(tab_id, state="hidden")
                    except Exception:
                        pass

            # 切换到阅读页签
            self._notebook.select(self._tab_reader)

            # 最大化窗口
            self.state('zoomed')

            # 更新按钮样式
            self._reader_max_btn.config(text="⛶ 退出最大化", bg=ACCENT)
        else:
            # ── 退出最大化 ──
            self._reader_maximized = False

            # 先恢复窗口状态（在布局恢复之前）
            self.state('normal')
            if self._reader_max_restore_geo:
                self.geometry(self._reader_max_restore_geo)

            # 恢复 body 边距
            self._body_frame.pack_forget()
            self._body_frame.pack(fill=tk.BOTH, expand=True, padx=10, pady=8)

            # 恢复工具栏手柄（必须先pack，top_bar_frame 依赖它作为 before 锚点）
            if not self._toolbar_handle_frame.winfo_ismapped():
                self._toolbar_handle_frame.pack(fill=tk.X, before=self._body_frame)

            # 恢复顶部工具栏
            if not self._top_bar_frame.winfo_ismapped():
                self._top_bar_frame.pack(fill=tk.X, before=self._toolbar_handle_frame)

            # 恢复所有页签
            for tab_id in self._notebook.tabs():
                try:
                    self._notebook.tab(tab_id, state="normal")
                except Exception:
                    pass

            # 更新按钮样式
            self._reader_max_btn.config(text="⛶ 最大化阅读", bg="#454b63")

    # ════════════════════════════════════════════════════════════════
    # 顶部细条 - 激励语（自由编辑）
    # ════════════════════════════════════════════════════════════════

    def _edit_motivation_text(self):
        """点击顶部的激励语 → 弹出小窗口编辑文字和颜色。"""
        win = tk.Toplevel(self)
        win.title("编辑激励语")
        win.configure(bg=BG)
        win.geometry("380x200")
        win.resizable(False, False)
        win.transient(self)
        win.grab_set()

        tk.Label(win, text="写点什么激励自己吧：", bg=BG, fg=TEXT,
                 font=("Microsoft YaHei UI", 9)).pack(pady=(16, 6))
        var = tk.StringVar(value=self._motivation_text.get())
        entry = tk.Entry(win, textvariable=var, bg=ENTRY, fg=TEXT,
                          insertbackground=TEXT, relief=tk.FLAT,
                          font=("Microsoft YaHei UI", 10), justify=tk.CENTER)
        entry.pack(fill=tk.X, padx=20, ipady=6)
        entry.focus_set()
        entry.select_range(0, tk.END)

        # 文字颜色选择
        color_var = tk.StringVar(value=self._motivation_color)
        color_row = tk.Frame(win, bg=BG)
        color_row.pack(fill=tk.X, padx=20, pady=(8, 0))
        tk.Label(color_row, text="文字颜色:", bg=BG, fg=TEXT,
                 font=("Microsoft YaHei UI", 9)).pack(side=tk.LEFT)
        color_preview = tk.Canvas(color_row, bg=color_var.get(), width=24, height=24,
                                  highlightthickness=1, highlightbackground=BORDER)
        color_preview.pack(side=tk.LEFT, padx=8)
        RoundedButton(color_row, text="选择颜色", bg=ENTRY, fg=TEXT,
                  relief=tk.FLAT, font=("Microsoft YaHei UI", 8),
                  padx=8, pady=3, cursor="hand2",
                  command=lambda: _pick_color()).pack(side=tk.LEFT)

        def _pick_color():
            color = colorchooser.askcolor(color=color_var.get(), title="选择激励语文字颜色", parent=win)
            if color and color[1]:
                color_var.set(color[1])
                color_preview.config(bg=color[1])

        def confirm():
            text = var.get().strip()
            self._motivation_text.set(text if text else "今天也要高效拿下任务！💪")
            self._motivation_color = color_var.get()
            self._save_config()
            self._motivation_reset_scroll()
            win.destroy()

        btn_row = tk.Frame(win, bg=BG)
        btn_row.pack(pady=16)
        RoundedButton(btn_row, text="保存", command=confirm, bg=ACCENT, fg="white",
                  relief=tk.FLAT, padx=18, pady=5, cursor="hand2",
                  font=("Microsoft YaHei UI", 9, "bold")).pack(side=tk.LEFT, padx=6)
        RoundedButton(btn_row, text="取消", command=win.destroy, bg="#454b63", fg="white",
                  relief=tk.FLAT, padx=18, pady=5, cursor="hand2",
                  font=("Microsoft YaHei UI", 9)).pack(side=tk.LEFT, padx=6)
        entry.bind("<Return>", lambda e: confirm())

    def _motivation_reset_scroll(self):
        """
        重新画名言文字并把滚动位置归零——文字内容变化、窗口尺寸变化（触发
        <Configure>）都需要调用这个，重新测量文字宽度才能让滚动循环正确。
        """
        if not hasattr(self, "_motivation_canvas"):
            return
        canvas = self._motivation_canvas
        canvas.delete("all")
        text = self._motivation_text.get()
        canvas_w = max(60, canvas.winfo_width())
        start_x = canvas_w  # 文字从画布右边缘之外开始，逐渐往左移动
        self._motivation_text_id = canvas.create_text(
            start_x, 12, text=text, fill=self._motivation_color, anchor="w",
            font=("Microsoft YaHei UI", 9, "bold"))
        self._motivation_scroll_x = float(start_x)
        if self._motivation_scroll_job:
            try:
                self.after_cancel(self._motivation_scroll_job)
            except Exception:
                pass
        self._motivation_scroll_job = self.after(30, self._motivation_scroll_tick)

    def _motivation_scroll_tick(self):
        """
        跑马灯滚动：文字从画布右侧进入，匀速向左移动，完全移出左边界后
        立刻从右侧重新开始——视觉上是"从右往左划过"，但对阅读者来说，
        每个字依次从右边出现、往左边走，最终呈现的是从左到右的阅读顺序，
        循环往复，不会停下来。
        """
        if not hasattr(self, "_motivation_canvas") or self._motivation_text_id is None:
            return
        canvas = self._motivation_canvas
        try:
            bbox = canvas.bbox(self._motivation_text_id)
        except tk.TclError:
            return  # 控件可能已经被销毁（比如程序正在关闭）
        if bbox is None:
            self._motivation_scroll_job = self.after(30, self._motivation_scroll_tick)
            return
        text_width = bbox[2] - bbox[0]
        speed = 1.5  # 每帧移动的像素数，决定滚动快慢
        self._motivation_scroll_x -= speed
        canvas.coords(self._motivation_text_id, self._motivation_scroll_x, 12)
        # 文字完全移出画布左边界（包括左侧padding）之后，重置到右边界外重新开始
        if self._motivation_scroll_x + text_width < -10:
            canvas_w = max(60, canvas.winfo_width())
            self._motivation_scroll_x = float(canvas_w)
            canvas.coords(self._motivation_text_id, self._motivation_scroll_x, 12)
        self._motivation_scroll_job = self.after(30, self._motivation_scroll_tick)

    # ════════════════════════════════════════════════════════════════
    # 顶部细条 - 番茄时钟
    # ════════════════════════════════════════════════════════════════

    def _format_pomodoro_time(self):
        """把当前剩余秒数格式化成"25:00"这种纯数字文字（不含图标，给各个绘制风格自己拼装图标/装饰）。"""
        m, s = divmod(max(0, self._pomodoro_remaining), 60)
        return f"{m:02d}:{s:02d}"

    def _pomodoro_urgency_color(self):
        """
        根据剩余时间决定颜色——快结束时变红、还剩几分钟时变橙、时间充裕
        时用主题色，是很常见的"科技感倒计时"配色逻辑：越紧迫颜色越警示。
        """
        if self._pomodoro_remaining <= 60:
            return "#ff4d6d"
        if self._pomodoro_remaining <= 300:
            return "#ffb84d"
        return "#2dd4a8" if self._pomodoro_mode == "work" else "#7c6cf0"

    def _pomodoro_redraw(self):
        """按当前选中的视觉风格，把倒计时画到Canvas上（每次时间变化都会调用一次）。"""
        if not hasattr(self, "_pomodoro_canvas"):
            return
        canvas = self._pomodoro_canvas
        canvas.delete("all")
        w = canvas.winfo_width() or 92
        h = canvas.winfo_height() or 26
        time_text = self._format_pomodoro_time()
        color = self._pomodoro_urgency_color()
        style = self._pomodoro_style
        if style == "ring":
            self._pomodoro_draw_ring(canvas, w, h, time_text, color)
        elif style == "glow":
            self._pomodoro_draw_glow(canvas, w, h, time_text, color)
        elif style == "pulse":
            self._pomodoro_draw_pulse(canvas, w, h, time_text, color)
        else:
            self._pomodoro_draw_classic(canvas, w, h, time_text, color)

    def _pomodoro_draw_classic(self, canvas, w, h, time_text, color):
        """经典风格：图标+文字，最朴素、最不打扰的样式。"""
        icon = "🍅" if self._pomodoro_mode == "work" else "☕"
        canvas.create_text(
            w / 2, h / 2, text=f"{icon} {time_text}", fill=color,
            font=("Consolas", 10, "bold"))

    def _pomodoro_draw_glow(self, canvas, w, h, time_text, color):
        """
        数字荧光风：模拟文字"发光"的效果——先在主文字周围偏移1像素的
        几个方向画几层更暗的"影子"文字，再在最上面画一层最亮的文字，
        视觉上会有一点光晕扩散开的感觉，比纯色文字更有科技感。
        """
        font = ("Consolas", 12, "bold")
        cx, cy = w / 2, h / 2
        glow_color = _darken_color(color, 0.45)
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            canvas.create_text(cx + dx, cy + dy, text=time_text,
                                fill=glow_color, font=font)
        canvas.create_text(cx, cy, text=time_text, fill=color, font=font)

    def _pomodoro_draw_pulse(self, canvas, w, h, time_text, color):
        """
        脉冲呼吸风：冒号每秒闪烁一次（经典数字时钟的标志性效果），
        营造"在走动"的动态感，而不是一直显示同一个静止画面。
        """
        self._pomodoro_blink_on = not self._pomodoro_blink_on
        sep = ":" if self._pomodoro_blink_on else " "
        parts = time_text.split(":")
        display = parts[0] + sep + parts[1] if len(parts) == 2 else time_text
        icon = "🍅" if self._pomodoro_mode == "work" else "☕"
        canvas.create_text(
            w / 2, h / 2, text=f"{icon} {display}", fill=color,
            font=("Consolas", 10, "bold"))

    def _pomodoro_draw_ring(self, canvas, w, h, time_text, color):
        """
        环形进度风：画一个圆环表示当前阶段已经过去的时间比例，圆环中间
        放倒计时数字——常见于专业计时工具/仪表盘的"科技范"视觉语言。
        """
        total = max(1, (self._pomodoro_work_minutes if self._pomodoro_mode == "work"
                         else self._pomodoro_break_minutes) * 60)
        progress = 1.0 - (max(0, self._pomodoro_remaining) / total)  # 0~1，已经过去的比例
        size = min(h, 24)
        r = size / 2 - 2
        cx = r + 3
        cy = h / 2
        canvas.create_oval(cx - r, cy - r, cx + r, cy + r,
                            outline="#3a3f56", width=3)
        extent = -360.0 * max(0.0, min(1.0, progress))
        if abs(extent) > 1:
            canvas.create_arc(cx - r, cy - r, cx + r, cy + r,
                               start=90, extent=extent,
                               outline=color, width=3, style=tk.ARC)
        canvas.create_text(
            cx + r + 8 + (w - 2 * r - 14) / 2, cy, text=time_text,
            fill=color, font=("Consolas", 10, "bold"), anchor="center")

    def _toggle_pomodoro(self):
        """开始/暂停番茄时钟。"""
        if self._pomodoro_running:
            self._pomodoro_running = False
            self._pomodoro_toggle_btn.config(text="▶", bg="#454b63")
            if self._pomodoro_job:
                try:
                    self.after_cancel(self._pomodoro_job)
                except Exception:
                    pass
                self._pomodoro_job = None
        else:
            self._pomodoro_running = True
            self._pomodoro_toggle_btn.config(text="⏸", bg=ACCENT)
            self._pomodoro_tick()

    def _reset_pomodoro(self):
        """重置番茄时钟到当前阶段（工作/休息）的初始时长，并停止计时。"""
        self._pomodoro_running = False
        if self._pomodoro_job:
            try:
                self.after_cancel(self._pomodoro_job)
            except Exception:
                pass
            self._pomodoro_job = None
        self._pomodoro_toggle_btn.config(text="▶", bg="#454b63")
        minutes = (self._pomodoro_work_minutes if self._pomodoro_mode == "work"
                   else self._pomodoro_break_minutes)
        self._pomodoro_remaining = minutes * 60
        self._pomodoro_redraw()

    def _pomodoro_tick(self):
        """每秒走一次的倒计时回调。"""
        if not self._pomodoro_running:
            return
        self._pomodoro_redraw()
        if self._pomodoro_remaining <= 0:
            self._pomodoro_running = False
            self._pomodoro_toggle_btn.config(text="▶", bg="#454b63")
            self._on_pomodoro_finished()
            return
        self._pomodoro_remaining -= 1
        self._pomodoro_job = self.after(1000, self._pomodoro_tick)

    def _on_pomodoro_finished(self):
        """一个阶段（工作/休息）结束：显示大提醒弹窗，把窗口调到最前，自动切到下一阶段。"""
        try:
            self._bring_window_to_front()
        except Exception:
            pass
        if self._pomodoro_mode == "work":
            self._pomodoro_mode = "break"
            icon, title, subtitle = "🍅", "番茄时段完成！", "好好休息一下吧 ☕"
            accent = "#ff4d6d"
        else:
            self._pomodoro_mode = "work"
            icon, title, subtitle = "🚀", "休息结束！", "开始下一个专注时段 🍅"
            accent = "#2dd4a8"
        minutes = (self._pomodoro_work_minutes if self._pomodoro_mode == "work"
                   else self._pomodoro_break_minutes)
        self._pomodoro_remaining = minutes * 60
        self._pomodoro_redraw()
        self._show_pomodoro_finished_overlay(icon, title, subtitle, accent)

    def _show_pomodoro_finished_overlay(self, icon, title, subtitle, accent):
        """
        全屏级别的番茄时钟结束提醒——用一个覆盖整个主窗口的半透明悬浮层
        （Toplevel + overrideredirect）显示大图标、大标题、副标题、自定义图片和倒计时。
        自动5秒倒计时关闭，也可以点击任意位置或按任意键提前关闭。
        """
        ow = self.winfo_rootx()
        oh = self.winfo_rooty()
        ow_w = max(600, self.winfo_width())
        ow_h = max(400, self.winfo_height())

        overlay = tk.Toplevel(self)
        overlay.overrideredirect(True)
        overlay.attributes("-topmost", True)
        overlay.geometry(f"{ow_w}x{ow_h}+{ow}+{oh}")
        overlay.configure(bg="#000000")
        try:
            overlay.attributes("-alpha", 0.92)
        except Exception:
            pass

        canvas = tk.Canvas(overlay, bg="#0a0a0a", highlightthickness=0)
        canvas.pack(fill=tk.BOTH, expand=True)

        cx = ow_w / 2
        cy = ow_h / 2

        # ── 自定义图片：如果设置了且文件存在，加载并居中显示 ──
        custom_img_tk = None
        custom_img_w = 0
        custom_img_h = 0
        img_path = getattr(self, '_pomodoro_image_path', '')
        if img_path and os.path.isfile(img_path):
            try:
                pil_img = Image.open(img_path)
                # 缩放到不超过窗口的70%
                max_w = int(ow_w * 0.7)
                max_h = int(ow_h * 0.55)
                pil_img.thumbnail((max_w, max_h), Image.LANCZOS)
                custom_img_tk = ImageTk.PhotoImage(pil_img)
                custom_img_w = pil_img.width
                custom_img_h = pil_img.height
            except Exception:
                custom_img_tk = None

        if custom_img_tk:
            # 图片在上面，文字在下面
            img_x = cx - custom_img_w / 2
            img_y = cy - custom_img_h / 2 - 30
            canvas.create_image(cx, img_y + custom_img_h / 2,
                                image=custom_img_tk, anchor="center")
            # 把图片引用挂到 overlay 上防止被GC
            overlay._pomodoro_img = custom_img_tk

            text_cy = img_y + custom_img_h + 50
            # 大标题
            canvas.create_text(cx, text_cy, text=title,
                                font=("Microsoft YaHei UI", 24, "bold"),
                                fill="#ffffff", anchor="center")
            # 副标题
            canvas.create_text(cx, text_cy + 32, text=subtitle,
                                font=("Microsoft YaHei UI", 13),
                                fill=accent, anchor="center")
            # 倒计时提示
            countdown_y = text_cy + 60
        else:
            # 无图片 → 原有样式：发光圆 + 图标 + 标题
            r = min(ow_w, ow_h) * 0.32
            canvas.create_oval(cx - r, cy - r, cx + r, cy + r,
                                fill=accent, outline="", stipple="gray25")
            canvas.create_oval(cx - r * 0.85, cy - r * 0.85,
                                cx + r * 0.85, cy + r * 0.85,
                                fill="#0a0a0a", outline="")

            canvas.create_text(cx, cy - r * 0.25, text=icon,
                                font=("Segoe UI Emoji", 64), fill=accent, anchor="center")

            canvas.create_text(cx, cy + r * 0.25, text=title,
                                font=("Microsoft YaHei UI", 28, "bold"),
                                fill="#ffffff", anchor="center")

            canvas.create_text(cx, cy + r * 0.50, text=subtitle,
                                font=("Microsoft YaHei UI", 14),
                                fill=accent, anchor="center")

            countdown_y = cy + r * 0.75

        countdown_id = canvas.create_text(
            cx, countdown_y,
            text="5 秒后自动关闭  ·  点击任意处关闭",
            font=("Microsoft YaHei UI", 10), fill="#888888", anchor="center")

        # 尝试播放系统提示音
        try:
            import winsound
            winsound.MessageBeep(winsound.MB_ICONEXCLAMATION)
        except Exception:
            pass

        countdown_remaining = [5]

        def close_overlay(event=None):
            try:
                overlay.destroy()
            except Exception:
                pass

        def tick():
            if not overlay.winfo_exists():
                return
            countdown_remaining[0] -= 1
            if countdown_remaining[0] <= 0:
                close_overlay()
                return
            canvas.itemconfigure(
                countdown_id,
                text=f"{countdown_remaining[0]} 秒后自动关闭  ·  点击任意处关闭")
            overlay.after(1000, tick)

        overlay.bind("<Button-1>", close_overlay)
        overlay.bind("<Key>", close_overlay)
        overlay.focus_force()
        overlay.after(1000, tick)

    def _show_pomodoro_settings(self):
        """设置番茄时钟的工作/休息时长（分钟）、倒计时视觉风格和结束提醒图片，保存后立即生效。"""
        win = tk.Toplevel(self)
        win.title("番茄时钟设置")
        win.configure(bg=BG)
        win.geometry("360x530")
        win.resizable(False, False)
        win.transient(self)
        win.grab_set()

        form = tk.Frame(win, bg=BG)
        form.pack(fill=tk.BOTH, expand=True, padx=20, pady=16)

        tk.Label(form, text="工作时长（分钟）:", bg=BG, fg=TEXT,
                 font=("Microsoft YaHei UI", 9)).grid(row=0, column=0, sticky="w", pady=8)
        work_var = tk.StringVar(value=str(self._pomodoro_work_minutes))
        tk.Entry(form, textvariable=work_var, bg=ENTRY, fg=TEXT,
                 insertbackground=TEXT, relief=tk.FLAT, width=6,
                 font=("Microsoft YaHei UI", 9)).grid(row=0, column=1, padx=(10, 0), ipady=3)

        tk.Label(form, text="休息时长（分钟）:", bg=BG, fg=TEXT,
                 font=("Microsoft YaHei UI", 9)).grid(row=1, column=0, sticky="w", pady=8)
        break_var = tk.StringVar(value=str(self._pomodoro_break_minutes))
        tk.Entry(form, textvariable=break_var, bg=ENTRY, fg=TEXT,
                 insertbackground=TEXT, relief=tk.FLAT, width=6,
                 font=("Microsoft YaHei UI", 9)).grid(row=1, column=1, padx=(10, 0), ipady=3)

        tk.Label(form, text="倒计时显示风格:", bg=BG, fg=TEXT,
                 font=("Microsoft YaHei UI", 9)).grid(
            row=2, column=0, columnspan=2, sticky="w", pady=(14, 4))

        style_var = tk.StringVar(value=self._pomodoro_style)
        style_options = [
            ("ring", "🔘 环形进度 —— 圆环显示已过去的时间比例"),
            ("glow", "✨ 数字荧光 —— 文字带发光效果"),
            ("pulse", "💓 脉冲呼吸 —— 冒号每秒闪烁"),
            ("classic", "📝 经典文字 —— 最朴素，不打扰"),
        ]
        preview_box = tk.Canvas(form, bg=PANEL, width=110, height=30,
                                 highlightthickness=0, bd=0)
        preview_box.grid(row=3, column=0, columnspan=2, pady=(2, 8))

        def refresh_preview():
            preview_box.update_idletasks()
            preview_box.delete("all")
            saved_style = self._pomodoro_style
            self._pomodoro_style = style_var.get()
            old_canvas = self._pomodoro_canvas
            self._pomodoro_canvas = preview_box
            try:
                self._pomodoro_redraw()
            finally:
                self._pomodoro_canvas = old_canvas
                self._pomodoro_style = saved_style

        for i, (val, label) in enumerate(style_options):
            tk.Radiobutton(
                form, text=label, value=val, variable=style_var,
                command=refresh_preview, bg=BG, fg=TEXT, selectcolor=ENTRY,
                activebackground=BG, activeforeground=TEXT,
                font=("Microsoft YaHei UI", 8), anchor="w",
            ).grid(row=4 + i, column=0, columnspan=2, sticky="w")

        refresh_preview()

        # ── 结束提醒图片 ──
        tk.Frame(form, bg=BORDER, height=1).grid(
            row=8, column=0, columnspan=2, sticky="ew", pady=(12, 8))

        tk.Label(form, text="🖼 倒计时结束弹出图片:", bg=BG, fg=TEXT,
                 font=("Microsoft YaHei UI", 9)).grid(
            row=9, column=0, columnspan=2, sticky="w", pady=(0, 4))

        img_path_var = tk.StringVar(value=self._pomodoro_image_path)
        img_status_var = tk.StringVar()
        def _update_img_status():
            p = img_path_var.get()
            if p and os.path.isfile(p):
                img_status_var.set(f"✓ {os.path.basename(p)}")
            elif p:
                img_status_var.set("⚠ 文件不存在")
            else:
                img_status_var.set("（未设置）")

        _update_img_status()

        img_row = tk.Frame(form, bg=BG)
        img_row.grid(row=10, column=0, columnspan=2, sticky="ew", pady=(0, 4))
        tk.Label(img_row, textvariable=img_status_var, bg=BG, fg=DIM,
                 font=("Microsoft YaHei UI", 8), anchor="w").pack(side=tk.LEFT, fill=tk.X, expand=True)

        btn_img_row = tk.Frame(form, bg=BG)
        btn_img_row.grid(row=11, column=0, columnspan=2, sticky="ew")
        RoundedButton(btn_img_row, text="📁 选择图片", bg=ACCENT, fg="white",
                  relief=tk.FLAT, font=("Microsoft YaHei UI", 8, "bold"),
                  padx=10, pady=4, cursor="hand2",
                  command=lambda: _browse_image()).pack(side=tk.LEFT, padx=(0, 6))
        RoundedButton(btn_img_row, text="✖ 清除", bg="#454b63", fg="white",
                  relief=tk.FLAT, font=("Microsoft YaHei UI", 8),
                  padx=8, pady=4, cursor="hand2",
                  command=lambda: _clear_image()).pack(side=tk.LEFT)

        def _browse_image():
            path = filedialog.askopenfilename(
                title="选择结束提醒图片",
                filetypes=[("图片文件", "*.png *.jpg *.jpeg *.gif *.bmp *.webp"),
                           ("所有文件", "*.*")],
                parent=win)
            if path:
                img_path_var.set(path)
                _update_img_status()

        def _clear_image():
            img_path_var.set("")
            _update_img_status()

        def confirm():
            try:
                w = max(1, min(180, int(work_var.get())))
                b = max(1, min(60, int(break_var.get())))
            except ValueError:
                messagebox.showwarning("输入有误", "请输入数字。", parent=win)
                return
            self._pomodoro_work_minutes = w
            self._pomodoro_break_minutes = b
            self._pomodoro_style = style_var.get()
            self._pomodoro_image_path = img_path_var.get()
            self._save_config()
            self._reset_pomodoro()
            win.destroy()

        btn_row = tk.Frame(win, bg=BG)
        btn_row.pack(pady=(4, 14))
        RoundedButton(btn_row, text="保存", command=confirm, bg=ACCENT, fg="white",
                  relief=tk.FLAT, padx=18, pady=5, cursor="hand2",
                  font=("Microsoft YaHei UI", 9, "bold")).pack(side=tk.LEFT, padx=6)
        RoundedButton(btn_row, text="取消", command=win.destroy, bg="#454b63", fg="white",
                  relief=tk.FLAT, padx=18, pady=5, cursor="hand2",
                  font=("Microsoft YaHei UI", 9)).pack(side=tk.LEFT, padx=6)

    def _show_app_theme_menu(self):
        """显示程序全局外观主题菜单。"""
        palette = self._active_app_palette
        menu = tk.Menu(
            self, tearoff=0, bg=palette["PANEL"], fg=palette["TEXT"],
            activebackground=palette["ACCENT"], activeforeground="white",
            selectcolor=palette["CARD"], font=("Microsoft YaHei UI", 9))
        xiaomi_keys = set(getattr(self, "_xiaomi_theme_keys", ()))
        sep_added = False
        for key, theme in self._app_themes.items():
            if key in xiaomi_keys and not sep_added:
                menu.add_separator()
                menu.add_command(label="—— 小米汽车色 ——", state="disabled")
                sep_added = True
            menu.add_radiobutton(
                label=theme["name"], variable=self._app_theme, value=key,
                command=self._apply_app_theme)
        x = self._app_theme_btn.winfo_rootx()
        y = self._app_theme_btn.winfo_rooty() + self._app_theme_btn.winfo_height()
        menu.post(x, y)

    # ── 小工具启动 ──
    _TOOLS = [
        ("🔁 dBm/mV 换算器", "Bode-100", "Bode-100-dbm-mV.py"),
        ("🖱 鼠标定位助手", "mouse-location", "mouse_location_try_3.py"),
    ]

    def _show_tools_menu(self):
        """弹出小工具菜单，选择后以独立进程启动对应工具。"""
        palette = self._active_app_palette
        menu = tk.Menu(
            self, tearoff=0, bg=palette["PANEL"], fg=palette["TEXT"],
            activebackground=palette["ACCENT"], activeforeground="white",
            selectcolor=palette["CARD"], font=("Microsoft YaHei UI", 9))
        for label, subdir, script in self._TOOLS:
            menu.add_command(
                label=label,
                command=lambda s=subdir, f=script: self._launch_tool(s, f))
        x = self._tools_btn.winfo_rootx()
        y = self._tools_btn.winfo_rooty() + self._tools_btn.winfo_height()
        menu.post(x, y)

    def _launch_tool(self, subdir, script):
        """用独立进程启动工具脚本，避免全局钩子/DPI 相互干扰。"""
        base = os.path.dirname(os.path.abspath(__file__))
        script_path = os.path.join(base, "tools", subdir, script)
        if not os.path.exists(script_path):
            messagebox.showerror("小工具", f"未找到工具脚本：\n{script_path}")
            return
        creationflags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        try:
            subprocess.Popen(
                [sys.executable, script_path],
                cwd=os.path.dirname(script_path),
                creationflags=creationflags)
        except Exception as e:
            messagebox.showerror("小工具", f"启动失败：{e}")

    @staticmethod
    def _derive_secondary_colors(palette):
        """根据主题明暗派生弹窗/浮层二级色（硬编码中性色的浅/深两套）。"""
        try:
            r, g, b = _hex_to_rgb(palette["BG"])
            dark = (0.299 * r + 0.587 * g + 0.114 * b) < 128
        except Exception:
            dark = True
        if dark:
            return {"POPUP_BG": "#1a1a1a", "POPUP_CARD": "#2d2d2d",
                    "POPUP_DIM": "#999999"}
        return {"POPUP_BG": "#f5f5f5", "POPUP_CARD": "#ffffff",
                "POPUP_DIM": "#666666"}

    def _apply_app_theme(self, persist=True):
        """动态更新经典Tk控件与ttk控件的全局配色。"""
        theme_key = self._app_theme.get()
        if theme_key not in self._app_themes:
            theme_key = "graphite"
            self._app_theme.set(theme_key)
        old = self._active_app_palette
        new = self._app_themes[theme_key]
        color_map = {
            str(old[key]).lower(): new[key]
            for key in ("BG", "PANEL", "CARD", "ENTRY", "BORDER",
                        "ACCENT", "GREEN", "TEXT", "DIM", "CANVAS")
        }

        def recolor(widget):
            if isinstance(widget, (RoundedButton, SlimScrollbar)):
                widget._refresh_theme(color_map, new)
                return
            try:
                keys = set(widget.keys())
            except Exception:
                keys = set()
            updates = {}
            for option in (
                    "background", "foreground", "activebackground",
                    "activeforeground", "selectcolor", "insertbackground",
                    "highlightbackground", "highlightcolor", "troughcolor"):
                if option not in keys:
                    continue
                try:
                    current = str(widget.cget(option)).lower()
                except Exception:
                    continue
                if current in color_map:
                    updates[option] = color_map[current]
            if updates:
                try:
                    widget.configure(**updates)
                except Exception:
                    pass
            try:
                children = widget.winfo_children()
            except Exception:
                children = ()
            for child in children:
                recolor(child)

        recolor(self)
        globals().update({key: new[key] for key in (
            "BG", "PANEL", "CARD", "ENTRY", "BORDER",
            "ACCENT", "GREEN", "TEXT", "DIM", "CANVAS")})
        # 派生二级色随主题明暗切换（弹窗背景等硬编码中性色跟随主题）
        globals().update(self._derive_secondary_colors(new))
        self._active_app_palette = dict(new)
        self._reader_themes["normal"]["canvas_bg"] = new["CANVAS"]
        self.configure(bg=new["BG"])
        self._app_theme_btn.config(
            text=f"✦ {new['name']}", bg=new["ENTRY"], fg=new["TEXT"])

        style = ttk.Style()
        style.theme_use("clam")
        style.configure("TNotebook", background=new["BG"], borderwidth=0)
        style.configure("TEntry", borderwidth=0, relief="flat")
        style.configure("TCombobox", borderwidth=0)
        style.configure(
            "TNotebook.Tab", background=new["PANEL"], foreground=new["TEXT"],
            padding=(12, 6))
        style.map(
            "TNotebook.Tab",
            background=[("selected", new["ACCENT"])],
            foreground=[("selected", "white")])
        style.configure(
            "Treeview", background=new["CARD"], foreground=new["TEXT"],
            fieldbackground=new["CARD"], borderwidth=0)
        style.configure(
            "Treeview.Heading", background=new["PANEL"], foreground=new["TEXT"])
        style.map("Treeview", background=[("selected", new["ACCENT"])])
        style.configure(
            "TScrollbar", background=new["PANEL"], troughcolor=new["BG"],
            arrowcolor=new["TEXT"])
        style.configure(
            "TCombobox", fieldbackground=new["ENTRY"], background=new["ENTRY"],
            foreground=new["TEXT"])
        if persist and hasattr(self, "_config_file"):
            self._save_config()

    def _on_mode_change(self):
        """模式切换时自动切换页签并启停轮询"""
        mode = self._mode.get()
        if mode == "compare":
            self._notebook.select(self._tab_compare)
            if self._poll_job:
                self.after_cancel(self._poll_job)
                self._poll_job = None
        else:
            self._notebook.select(self._tab_pdf)
            if mode == "follow":
                self._start_poll()

