        self._excel_report_tree.tag_configure("部分匹配", foreground="#ffe066")
        self._excel_report_tree.tag_configure("仅左表有", foreground="#69e59a")
        self._excel_report_tree.tag_configure("仅右表有", foreground="#ff7777")
