    def _on_cmp_sidebar_mode_change(self):
        """切换侧边栏显示：共用关键词 / Excel差异对比"""
        mode = self._cmp_sidebar_mode.get()
        if mode == "keyword":
            self._cmp_xldiff_panel.pack_forget()
            self._cmp_kw_panel.pack(fill=tk.BOTH, expand=True)
        else:
            self._cmp_kw_panel.pack_forget()
            self._cmp_xldiff_panel.pack(fill=tk.BOTH, expand=True)

    def _build_cmp_canvas(self, parent, col, tag):
        """构建单个对比画布（col=1左, col=2右）"""
        cw = 600 if col == 1 else 590
        frame = tk.Frame(parent, bg=CANVAS, width=cw,
                         highlightbackground=BORDER, highlightthickness=1)
        frame.grid(row=1, column=col, sticky="nsew")
        frame.rowconfigure(0, weight=1)
        frame.columnconfigure(0, weight=1)

        # ── 单页画布层 ──
        single_f = tk.Frame(frame, bg=CANVAS)
        single_f.grid(row=0, column=0, sticky="nsew")
        single_f.rowconfigure(0, weight=1)
        single_f.columnconfigure(0, weight=1)

        canvas = tk.Canvas(single_f, bg=CANVAS, highlightthickness=0)
        h_sc = ttk.Scrollbar(single_f, orient=tk.HORIZONTAL, command=canvas.xview)
        v_sc = ttk.Scrollbar(single_f, orient=tk.VERTICAL, command=canvas.yview)
        canvas.config(xscrollcommand=h_sc.set, yscrollcommand=v_sc.set)
        canvas.grid(row=0, column=0, sticky="nsew")
        v_sc.grid(row=0, column=1, sticky="ns")
        h_sc.grid(row=1, column=0, sticky="ew")

        # ── 多页缩略图层（初始隐藏）──
        multi_f = tk.Frame(frame, bg=CANVAS)
        # 不 grid，由 _show_multi_page / _exit_multi_page 控制

        # 事件绑定
        side_idx = 1 if tag == "left" else 2
        canvas.bind("<MouseWheel>", lambda e: self._zoom_cmp(e, side_idx))
        canvas.bind("<ButtonPress-1>", lambda e: self._on_cmp_canvas_click(e, side_idx))
        canvas.bind("<B1-Motion>", lambda e: canvas.scan_dragto(e.x, e.y, gain=1))

        if tag == "left":
            self._cmp_frame1 = frame
            self._cmp_single1 = single_f
            self._cmp_multi1 = multi_f
            self._cmp_canvas1 = canvas
            self._cmp_h1, self._cmp_v1 = h_sc, v_sc
        else:
            self._cmp_frame2 = frame
            self._cmp_single2 = single_f
            self._cmp_multi2 = multi_f
            self._cmp_canvas2 = canvas
            self._cmp_h2, self._cmp_v2 = h_sc, v_sc

    # ── 文件打开 ──

    def _open_pdf_left(self):
        path = filedialog.askopenfilename(
            title="打开左侧PDF",
            filetypes=[("PDF文件", "*.pdf"), ("所有文件", "*.*")])
        if path:
            new_doc = self._load_pdf_document(path)
            if new_doc is None:
                return
            if self._pdf_doc1:
                self._pdf_word_cache.pop(id(self._pdf_doc1), None)
                self._pdf_doc1.close()
            self._pdf_doc1 = new_doc
            self._cur_page1 = 0
            self._scale1 = 1.0
            self._cmp_reset_active_highlight(1)
            self._cmp_auto_fit_scale(1)
            self._render_compare_page(1)
            self._update_cmp_page_label(1)
            self._cmp_status.set(f"左侧: {os.path.basename(path)}")

    def _open_pdf_right(self):
        path = filedialog.askopenfilename(
            title="打开右侧PDF",
            filetypes=[("PDF文件", "*.pdf"), ("所有文件", "*.*")])
        if path:
            new_doc = self._load_pdf_document(path)
            if new_doc is None:
                return
            if self._pdf_doc2:
                self._pdf_word_cache.pop(id(self._pdf_doc2), None)
                self._pdf_doc2.close()
            self._pdf_doc2 = new_doc
            self._cur_page2 = 0
            self._scale2 = 1.0
            self._cmp_reset_active_highlight(2)
            self._cmp_auto_fit_scale(2)
            self._render_compare_page(2)
            self._update_cmp_page_label(2)
            self._cmp_status.set(f"右侧: {os.path.basename(path)}")

    def _cmp_auto_fit_scale(self, side):
        """PDF对比标签页自动适应宽度"""
        doc = self._pdf_doc1 if side == 1 else self._pdf_doc2
        canvas = self._cmp_canvas1 if side == 1 else self._cmp_canvas2
        if not doc:
            return
        canvas.update_idletasks()
        canvas_w = canvas.winfo_width()
        if canvas_w <= 20:
            return
        page_w = doc[0].rect.width
        scale = (canvas_w / page_w) * (72.0 / self.PDF_DPI)
        scale = max(0.2, min(scale, 6.0))
        if side == 1:
            self._scale1 = scale
        else:
            self._scale2 = scale

    # ── 渲染 ──

    def _render_compare_page(self, side, highlight_words: set = None):
        """
        渲染对比模式下的单侧PDF页。
        side: 1=左, 2=右
        highlight_words:
          - None（默认/不传）：不改变当前高亮记忆，按上次设置的高亮继续渲染。
            这样缩放(_zoom_cmp)、翻页(_go_cmp_page)时高亮不会丢失。
          - 传入一个集合（包括空集合 set()）：更新该侧的高亮记忆并立即生效，
            空集合表示清除高亮。
        """
        doc = self._pdf_doc1 if side == 1 else self._pdf_doc2
        page_idx = self._cur_page1 if side == 1 else self._cur_page2
        scale = self._scale1 if side == 1 else self._scale2
        canvas = self._cmp_canvas1 if side == 1 else self._cmp_canvas2
        img_attr = '_tk_img1' if side == 1 else '_tk_img2'

        if highlight_words is not None:
            self._cmp_active_hl[side] = set(highlight_words)

        if not doc:
            canvas.delete("all")
            return

        page = doc[page_idx]
        zoom = self.PDF_DPI / 72.0 * scale
        pix = page.get_pixmap(matrix=fitz.Matrix(zoom, zoom), alpha=False)
        img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)

        active_hl = self._cmp_active_hl.get(side)
        if active_hl:
            draw = ImageDraw.Draw(img, "RGBA")
            hl_r, hl_g, hl_b = self._cmp_hl_color
            for w in page.get_text("words"):
                word = self._clean_word(w[4])
                if word in active_hl:
                    x0 = int(w[0] * zoom); y0 = int(w[1] * zoom)
                    x1 = int(w[2] * zoom); y1 = int(w[3] * zoom)
                    draw.rectangle([x0, y0, x1, y1],
                                   outline=(hl_r, hl_g, hl_b, 255), width=1)
            del draw

        # 居中显示
        canvas.update_idletasks()
        canvas_w = canvas.winfo_width()
        x_offset = max(0, (canvas_w - pix.width) // 2)
        tk_img = ImageTk.PhotoImage(img)
        setattr(self, img_attr, tk_img)
        canvas.delete("all")
        canvas.create_image(x_offset, 0, anchor="nw", image=tk_img)
        canvas.config(scrollregion=canvas.bbox("all"))

    def _cmp_reset_active_highlight(self, side=None):
        """重置高亮记忆（不重新渲染）。side为None时两侧都重置。"""
        if side is None:
            self._cmp_active_hl[1] = set()
            self._cmp_active_hl[2] = set()
        else:
            self._cmp_active_hl[side] = set()

    def _render_both_pages(self, hl1: set = None, hl2: set = None):
        """同时渲染两侧PDF"""
        self._render_compare_page(1, hl1)
        self._render_compare_page(2, hl2)

    # ── 翻页 & 缩放 ──

    def _go_cmp_page(self, delta, side):
        doc = self._pdf_doc1 if side == 1 else self._pdf_doc2
        if not doc:
            return
        cur = self._cur_page1 if side == 1 else self._cur_page2
        new = cur + delta
        if 0 <= new < doc.page_count:
            if side == 1:
                self._cur_page1 = new
            else:
                self._cur_page2 = new
            self._render_compare_page(side)
            self._update_cmp_page_label(side)

    def _zoom_cmp(self, event, side):
        scale = self._scale1 if side == 1 else self._scale2
        scale *= 1.1 if event.delta > 0 else 0.9
        scale = max(0.2, min(scale, 6.0))
        if side == 1:
            self._scale1 = scale
        else:
            self._scale2 = scale
        self._render_compare_page(side)

    def _update_cmp_page_label(self, side):
        doc = self._pdf_doc1 if side == 1 else self._pdf_doc2
        cur = self._cur_page1 if side == 1 else self._cur_page2
        lbl = self._cmp_page_lbl1 if side == 1 else self._cmp_page_lbl2
        if doc:
            lbl.config(text=f"{cur+1}/{doc.page_count}")
        else:
            lbl.config(text="—")

    # ── 点击同步 ──

    def _on_cmp_canvas_click(self, event, side):
        """点击PDF画布时识别点击的词，双侧进入多页展开视图"""
        doc = self._pdf_doc1 if side == 1 else self._pdf_doc2
        cur_page = self._cur_page1 if side == 1 else self._cur_page2
        scale = self._scale1 if side == 1 else self._scale2
        if not doc:
            return

        page = doc[cur_page]
        zoom = self.PDF_DPI / 72.0 * scale
        canvas = self._cmp_canvas1 if side == 1 else self._cmp_canvas2
        canvas_x = canvas.canvasx(event.x)
        canvas_y = canvas.canvasy(event.y)
        pdf_x = canvas_x / zoom
        pdf_y = canvas_y / zoom

        clicked_word = None
        for w in page.get_text("words"):
            x0, y0, x1, y1 = w[0], w[1], w[2], w[3]
            if x0 <= pdf_x <= x1 and y0 <= pdf_y <= y1:
                clicked_word = self._clean_word(w[4])
                break

        if not clicked_word:
            canvas.scan_mark(event.x, event.y)
            return

        self._cmp_last_click = (side, clicked_word)
        self._cmp_status.set(f"点击了{'左' if side==1 else '右'}侧: {clicked_word}")

        # 先同步另一侧的单页视图（跳转到匹配页 + 高亮）
        self._sync_to_word(side, clicked_word)
        # 然后双侧进入多页展开视图
        self._show_multi_page(clicked_word)

    def _sync_to_word(self, from_side, word):
        """
        将另一侧PDF同步到包含该词的位置。
        from_side: 点击来源侧 (1或2)
        word: 要搜索的词
        """
        other_side = 2 if from_side == 1 else 1
        other_doc = self._pdf_doc1 if other_side == 1 else self._pdf_doc2
        if not other_doc:
            self._cmp_status.set(f"另一侧未加载PDF")
            return

        # 在另一侧PDF的所有页面中搜索该词
        found = False
        for pg_idx in range(other_doc.page_count):
            page = other_doc[pg_idx]
            matched_rects = []
            for w in page.get_text("words"):
                w_clean = self._clean_word(w[4])
                if w_clean.lower() == word.lower():
                    matched_rects.append([w[0], w[1], w[2], w[3]])

            if matched_rects:
                # 跳转到该页
                if other_side == 1:
                    self._cur_page1 = pg_idx
                else:
                    self._cur_page2 = pg_idx

                # 渲染并高亮
                hl_words = {word}
                self._render_compare_page(other_side, highlight_words=hl_words)
                self._update_cmp_page_label(other_side)

                # 居中到匹配位置
                canvas = self._cmp_canvas1 if other_side == 1 else self._cmp_canvas2
                scale = self._scale1 if other_side == 1 else self._scale2
                zoom = self.PDF_DPI / 72.0 * scale
                self._cmp_center_rects(canvas, matched_rects, zoom)
                found = True

                # 同时重新渲染来源侧，高亮被点击的词
                self._render_compare_page(from_side, highlight_words={word})
                break

        if not found:
            self._cmp_status.set(f"另一侧未找到关键词: {word}")

    def _cmp_center_rects(self, canvas, rects, zoom):
        """滚动画布使给定rects居中显示"""
        if not rects:
            return
        canvas.update_idletasks()
        canvas_w = canvas.winfo_width()
        canvas_h = canvas.winfo_height()
        if canvas_w <= 1 or canvas_h <= 1:
            return

        min_x = min(r[0]*zoom for r in rects)
        min_y = min(r[1]*zoom for r in rects)
        max_x = max(r[2]*zoom for r in rects)
        max_y = max(r[3]*zoom for r in rects)
        center_x = (min_x + max_x) / 2
        center_y = (min_y + max_y) / 2

        bbox = canvas.bbox("all")
        if not bbox:
            return
        content_w, content_h = bbox[2], bbox[3]
        scroll_x = max(0, center_x - canvas_w / 2) / content_w if content_w else 0
        scroll_y = max(0, center_y - canvas_h / 2) / content_h if content_h else 0
        canvas.xview_moveto(scroll_x)
        canvas.yview_moveto(scroll_y)

    # ── 交叉索引构建 ──

    def _build_cross_index(self):
        """
        扫描两份PDF所有页面，提取所有词。
        构建交叉索引: {word: {1: [(page, [rect]), ...], 2: [(page, [rect]), ...]}}
        识别器件位号 (R1, C101, U3, L2...) 并高亮显示。
        """
        doc1, doc2 = self._pdf_doc1, self._pdf_doc2
        if not doc1 and not doc2:
            messagebox.showwarning("未加载PDF", "请至少加载一份PDF文件")
            return

        self._cross_index = {}

        def scan_doc(doc, pdf_key):
            if not doc:
                return
            for pg_idx in range(doc.page_count):
                for w in doc[pg_idx].get_text("words"):
                    word = self._clean_word(w[4])
                    if not word or len(word) < 2:
                        continue
                    if word not in self._cross_index:
                        self._cross_index[word] = {1: [], 2: []}
                    if pdf_key not in self._cross_index[word]:
                        self._cross_index[word][pdf_key] = []
                    self._cross_index[word][pdf_key].append((
                        pg_idx, [w[0], w[1], w[2], w[3]]
                    ))

        scan_doc(doc1, 1)
        scan_doc(doc2, 2)

        self._refresh_cmp_index_list()
        self._cmp_status.set(
            f"索引构建完成: 共 {len(self._cross_index)} 个唯一关键词")

    def _refresh_cmp_index_list(self, filter_text: str = ""):
        """刷新侧边栏关键词列表"""
        self._cmp_idx_lb.delete(0, tk.END)
        if not self._cross_index:
            return

        # 按位号优先排序
        def sort_key(item):
            word = item[0]
            info = item[1]
            # 器件位号优先
            is_ref = bool(re.match(r'^[RCJLDUQFTY]P?\d+$', word, re.IGNORECASE))
            # 在两侧都出现的优先
            in_both = len(info.get(1, [])) > 0 and len(info.get(2, [])) > 0
            return (not in_both, not is_ref, word.lower())

        items = sorted(self._cross_index.items(), key=sort_key)

        filter_lower = filter_text.strip().lower()
        shown = 0
        for word, info in items:
            if filter_lower and filter_lower not in word.lower():
                continue
            in_a = len(info.get(1, []))
            in_b = len(info.get(2, []))
            # 器件位号标记
            is_ref = bool(re.match(r'^[RCJLDUQFTY]P?\d+$', word, re.IGNORECASE))
            prefix = "◆ " if is_ref else "  "
            if in_a > 0 and in_b > 0:
                suffix = f"  [{in_a}|{in_b}]"
                color_tag = "both"
            elif in_a > 0:
                suffix = f"  [L:{in_a}]"
                color_tag = "left"
            else:
                suffix = f"  [R:{in_b}]"
                color_tag = "right"

            self._cmp_idx_lb.insert(tk.END, f"{prefix}{word}{suffix}")
            shown += 1

        self._cmp_info_var.set(f"显示 {shown}/{len(self._cross_index)} 个关键词")

    def _on_cmp_filter(self, *args):
        self._refresh_cmp_index_list(self._cmp_filter_var.get())

    def _on_cmp_index_click(self, event):
        """点击侧边栏关键词时，在两侧PDF中同时定位"""
        sel = self._cmp_idx_lb.curselection()
        if not sel:
            return
        text = self._cmp_idx_lb.get(sel[0])
        m = re.match(r'^[◆ ]\s*(\S+)', text)
        if not m:
            return
        word = m.group(1)

        if self._pdf_doc1:
            self._sync_to_idx_word(1, word)
        if self._pdf_doc2:
            self._sync_to_idx_word(2, word)
        self._cmp_status.set(f"两侧同步到: {word}")

    def _on_cmp_index_dbl(self, event):
        """双击侧边栏关键词，两侧同时跳转"""
        self._on_cmp_index_click(event)

    def _sync_to_idx_word(self, side, word):
        """将指定侧的PDF跳转到包含该词的页面"""
        doc = self._pdf_doc1 if side == 1 else self._pdf_doc2
        if not doc:
            return

        info = self._cross_index.get(word, {}).get(side, [])
        if not info:
            return

        pg_idx, rect = info[0]
        if side == 1:
            self._cur_page1 = pg_idx
        else:
            self._cur_page2 = pg_idx

        self._render_compare_page(side, highlight_words={word})
        self._update_cmp_page_label(side)

        canvas = self._cmp_canvas1 if side == 1 else self._cmp_canvas2
        scale = self._scale1 if side == 1 else self._scale2
        zoom = self.PDF_DPI / 72.0 * scale
        self._cmp_center_rects(canvas, [rect], zoom)

    def _pick_cmp_color(self):
        """弹出颜色选择器，更新对比模式高亮颜色。"""
        init_color = "#{:02x}{:02x}{:02x}".format(*self._cmp_hl_color)
        result = colorchooser.askcolor(color=init_color, title="选择对比高亮颜色")
        if result and result[0]:
            r, g, b = (int(x) for x in result[0])
            self._cmp_hl_color = (r, g, b)
            hex_color = "#{:02x}{:02x}{:02x}".format(r, g, b)
            self._cmp_color_preview.config(bg=hex_color)
            # 如果当前在多页视图，重新渲染缩略图
            if self._cmp_multi_btn.winfo_ismapped():
                last = self._cmp_last_click
                if last:
                    self._show_multi_page(last[1])

    def _clear_cmp(self):
        """清除对比模式状态"""
        self._exit_multi_page()
        self._cross_index = {}
        self._cmp_last_click = None
        self._cmp_idx_lb.delete(0, tk.END)
        self._cmp_info_var.set("—")
        self._cmp_reset_active_highlight()
        self._render_both_pages()
        self._cmp_status.set("已清除")

    # ════════════════════════════════════════════════════════════════
    # PDF对比页签 - 内嵌Excel差异对比（独立连接，仅用于驱动PDF高亮，不修改Excel）
    # ════════════════════════════════════════════════════════════════

    def _xldiff_connect(self, side: int):
        """连接Excel 1或Excel 2（与「Excel对比」页签的连接完全独立）。"""
        if win32 is None:
            messagebox.showerror("缺少依赖", "请先安装 pywin32：\npip install pywin32")
            return
        other_wb = self._cmpxl_wb2 if side == 1 else self._cmpxl_wb1
        exclude = other_wb.Name if other_wb is not None else None
        title = f"选择 Excel {side} 文件 (对应{'左' if side == 1 else '右'}PDF)"
        choice = self._show_workbook_chooser(title, exclude_wb_name=exclude)
        if choice is None:
            return
        name = f"{choice['app_name']}: {choice['wb_name']}"
        if side == 1:
            self._cmpxl_app1 = choice["app"]
            self._cmpxl_wb1 = choice["wb"]
            self._cmpxl_name1 = name
            self._cmpxl1_status.set(f"✅ {name}")
        else:
            self._cmpxl_app2 = choice["app"]
            self._cmpxl_wb2 = choice["wb"]
            self._cmpxl_name2 = name
            self._cmpxl2_status.set(f"✅ {name}")
        self._cmp_status.set(f"[Excel {side}] 已连接 {name}")

    def _xldiff_compare(self):
        """
        对比 Excel1/Excel2 指定列，提取「仅左独有」/「仅右独有」的器件位号差异。
        仅用于读取分析，不会修改任何Excel单元格（高亮/批注都只发生在PDF端）。
        """
        if self._cmpxl_app1 is None:
            messagebox.showwarning("未连接", "请先连接 Excel 1（对应左PDF）")
            return
        if self._cmpxl_app2 is None:
            messagebox.showwarning("未连接", "请先连接 Excel 2（对应右PDF）")
            return

        try:
            row1 = int(self._cmpxl1_row.get())
        except ValueError:
            row1 = 2
        try:
            row2 = int(self._cmpxl2_row.get())
        except ValueError:
            row2 = 2

        try:
            self._cmp_status.set("正在读取 Excel 1...")
            self.update_idletasks()
            src1 = self._cmpxl_wb1 if self._cmpxl_wb1 is not None else self._cmpxl_app1
            cells1 = self._read_column_cells(src1, self._cmpxl1_col.get(), row1)

            self._cmp_status.set("正在读取 Excel 2...")
            self.update_idletasks()
            src2 = self._cmpxl_wb2 if self._cmpxl_wb2 is not None else self._cmpxl_app2
            cells2 = self._read_column_cells(src2, self._cmpxl2_col.get(), row2)
        except Exception as e:
            messagebox.showerror("读取失败", str(e))
            return

        if not cells1 and not cells2:
            messagebox.showinfo("对比完成", "两个Excel指定列均为空，无数据可对比。")
            return

        self._cmp_status.set("正在分析位号差异...")
        self.update_idletasks()
        matches, left_unmatched, right_unmatched = self._greedy_match_cells(
            cells1, cells2, threshold=0.5)

        # ── 汇总成「仅左独有 / 仅右独有」的扁平化位号列表 ──
        left_tokens = {}   # token -> list[addr]
        right_tokens = {}

        for li, ri, sim, left_only, right_only in matches:
            lc, rc = cells1[li], cells2[ri]
            for tok in left_only:
                left_tokens.setdefault(tok, []).append(f"R{lc['row']}C{lc['col']}")
            for tok in right_only:
                right_tokens.setdefault(tok, []).append(f"R{rc['row']}C{rc['col']}")

        for li in left_unmatched:
            lc = cells1[li]
            for tok in lc['tokens']:
                left_tokens.setdefault(tok, []).append(f"R{lc['row']}C{lc['col']}")

        for ri in right_unmatched:
            rc = cells2[ri]
            for tok in rc['tokens']:
                right_tokens.setdefault(tok, []).append(f"R{rc['row']}C{rc['col']}")

        # 同一个位号如果两边都"独有"过（理论上不会发生，因为独有=不在对方tokens集合里），
        # 这里仍做一次互斥裁剪，保险起见。
        records = []
        for tok, addrs in left_tokens.items():
            records.append({"token": tok, "status": "仅左表独有", "addrs": addrs})
        for tok, addrs in right_tokens.items():
            records.append({"token": tok, "status": "仅右表独有", "addrs": addrs})

        self._xldiff_records = records
        self._refresh_xldiff_list(self._xldiff_filter_var.get())

        n_left, n_right = len(left_tokens), len(right_tokens)
        self._xldiff_stats_var.set(
            f"Excel1: {len(cells1)} 格 / Excel2: {len(cells2)} 格\n"
            f"🟢 仅左表独有位号: {n_left}\n"
            f"🔴 仅右表独有位号: {n_right}")
        self._cmp_status.set(
            f"位号差异对比完成：仅左{n_left}个，仅右{n_right}个")

    def _refresh_xldiff_list(self, filter_text: str = ""):
        """刷新Excel差异列表（按状态分组，颜色区分）。"""
        self._xldiff_lb.delete(0, tk.END)
        self._xldiff_listed_tokens = []
        if not self._xldiff_records:
            return

        clr_left = "#{:06x}".format(XL_COLOR_LEFT & 0xFFFFFF)
        clr_right = "#{:06x}".format(XL_COLOR_RIGHT & 0xFFFFFF)

        filter_lower = filter_text.strip().lower()
        items = sorted(self._xldiff_records, key=lambda r: (r["status"], r["token"].lower()))

        for rec in items:
            if filter_lower and filter_lower not in rec["token"].lower():
                continue
            tag = "[仅左表]" if rec["status"] == "仅左表独有" else "[仅右表]"
            line = f"{rec['token']}  {tag}"
            idx = self._xldiff_lb.size()
            self._xldiff_lb.insert(tk.END, line)
            color = clr_left if rec["status"] == "仅左表独有" else clr_right
            self._xldiff_lb.itemconfig(idx, fg=color)
            self._xldiff_listed_tokens.append(rec["token"])

    def _on_xldiff_filter(self, *args):
        self._refresh_xldiff_list(self._xldiff_filter_var.get())

    def _xldiff_find_pages_with_tokens(self, doc, tokens: set) -> dict:
        """
        扫描doc的【全部页面】，返回 {page_idx: set(该页命中的tokens)}，
        只包含真正有命中的页（不限于第一页）。
        """
        result = {}
        if not doc or not tokens:
            return result
        tokens_lower = {t.lower(): t for t in tokens}
        for pg_idx in range(doc.page_count):
            hits = set()
            for w in doc[pg_idx].get_text("words"):
                word = self._clean_word(w[4])
                orig = tokens_lower.get(word.lower())
                if orig:
                    hits.add(orig)
            if hits:
                result[pg_idx] = hits
        return result

    def _get_multi_word_rects(self, page, tokens: set) -> dict:
        """返回页面上多个目标词各自的包围矩形：{token: [fitz.Rect, ...]}"""
        tokens_lower = {t.lower(): t for t in tokens}
        result = {}
        for w in page.get_text("words"):
            word = self._clean_word(w[4])
            orig = tokens_lower.get(word.lower())
            if orig:
                result.setdefault(orig, []).append(fitz.Rect(w[0], w[1], w[2], w[3]))
        return result

    def _xldiff_highlight(self, target):
        """
        将差异位号在指定PDF的【全部页面】中查找并高亮显示。
        target: 1=左PDF, 2=右PDF, 'both'=两侧都高亮

        - 如果在差异列表中选中了某些条目：只高亮选中的那些位号（精确控制）。
        - 如果没有选中任何条目：默认对【全部】已对比出的差异位号生效
          （不需要先手动选择，点击按钮即可看到所有差异）。

        命中多页时自动展开多页缩略图视图，一次性看到所有命中位置，
        命中单页时直接定位到该页（不用额外点退出）。
        """
        sel = self._xldiff_lb.curselection()
        if sel:
            tokens = {self._xldiff_listed_tokens[i] for i in sel
                      if i < len(self._xldiff_listed_tokens)}
        else:
            tokens = {r["token"] for r in self._xldiff_records}

        if not tokens:
            messagebox.showinfo("没有差异", "请先点击「▶ 对比差异」生成差异列表")
            return

        token_status = {r["token"]: r["status"] for r in self._xldiff_records}

        sides = [1, 2] if target == "both" else [target]
        msgs = []
        multi_shown = False
        for side in sides:
            tag = "左" if side == 1 else "右"
            doc = self._pdf_doc1 if side == 1 else self._pdf_doc2
            if not doc:
                msgs.append(f"{tag}PDF未加载")
                continue

            page_hits = self._xldiff_find_pages_with_tokens(doc, tokens)
            if not page_hits:
                msgs.append(f"{tag}PDF中未找到所选位号")
                continue

            found_tokens = set()
            for hs in page_hits.values():
                found_tokens |= hs
            missing = tokens - found_tokens
            n_pages = len(page_hits)

            if n_pages == 1:
                # 只有一页命中：直接定位，无需展开缩略图
                pg_idx = next(iter(page_hits))
                if side == 1:
                    self._cur_page1 = pg_idx
                else:
                    self._cur_page2 = pg_idx
                self._render_compare_page(side, highlight_words=tokens)
                self._update_cmp_page_label(side)
                page = doc[pg_idx]
                scale = self._scale1 if side == 1 else self._scale2
                zoom = self.PDF_DPI / 72.0 * scale
                rects = [[w[0], w[1], w[2], w[3]] for w in page.get_text("words")
                         if self._clean_word(w[4]) in page_hits[pg_idx]]
                canvas = self._cmp_canvas1 if side == 1 else self._cmp_canvas2
                self._cmp_center_rects(canvas, rects, zoom)
                msg = f"{tag}PDF第{pg_idx+1}页"
            else:
                # 多页命中：展开缩略图网格，一次性全部高亮显示
                self._show_xldiff_multi_page_side(side, tokens, page_hits, token_status)
                multi_shown = True
                msg = f"{tag}PDF共{n_pages}页命中，已全部展开高亮"

            if missing:
                msg += f"（未找到: {', '.join(sorted(missing))}）"
            msgs.append(msg)

        if multi_shown:
            self._cmp_multi_btn.pack(side=tk.LEFT, padx=3, pady=6)
        self._cmp_status.set(" | ".join(msgs))

    def _show_xldiff_multi_page_side(self, side, tokens, page_hits, token_status):
        """单侧进入多页缩略图视图，展示该侧所有命中所选位号的页面。"""
        single = self._cmp_single1 if side == 1 else self._cmp_single2
        multi = self._cmp_multi1 if side == 1 else self._cmp_multi2
        single.grid_remove()
        multi.grid(row=0, column=0, sticky="nsew")
        page_indices = sorted(page_hits.keys())
        self._build_xldiff_thumbnails(multi, side, tokens, page_hits, token_status, page_indices)

    def _build_xldiff_thumbnails(self, parent, side, tokens, page_hits, token_status, page_indices):
        """
        构建Excel差异专用的多页缩略图网格：
        每张缩略图上，把该页命中的全部位号都框出来（绿=仅左表独有，红=仅右表独有），
        点击缩略图跳转回单页视图并保留全部已选位号的高亮。
        """
        for w in parent.winfo_children():
            w.destroy()

        parent.rowconfigure(0, weight=0)
        parent.rowconfigure(1, weight=1)
        parent.columnconfigure(0, weight=1)

        info_bar = tk.Frame(parent, bg=PANEL, height=32)
        info_bar.grid(row=0, column=0, sticky="ew")
        info_bar.pack_propagate(False)
        tag = "左" if side == 1 else "右"
        tk.Label(info_bar,
                 text=f"{tag}侧 - Excel差异位号命中 {len(page_indices)} 页（共{len(tokens)}个位号）",
                 bg=PANEL, fg=TEXT, font=("Microsoft YaHei UI", 9, "bold"),
                 padx=8).pack(side=tk.LEFT, pady=4)

        scroll_canvas = tk.Canvas(parent, bg="#e8e8e8", highlightthickness=0)
        scrollbar = ttk.Scrollbar(parent, orient=tk.VERTICAL, command=scroll_canvas.yview)
        scroll_canvas.config(yscrollcommand=scrollbar.set)

        thumb_container = tk.Frame(scroll_canvas, bg="white")
        scroll_canvas.create_window((0, 0), window=thumb_container, anchor="nw",
                                     tags="thumb_window")
        scroll_canvas.grid(row=1, column=0, sticky="nsew")
        scrollbar.grid(row=1, column=1, sticky="ns")

        doc = self._pdf_doc1 if side == 1 else self._pdf_doc2
        if not doc:
            return

        parent.update_idletasks()
        container_w = parent.winfo_width()
        if container_w < 100:
            container_w = 600

        PAD = 8
        MIN_COL_W = 200
        cols = max(1, container_w // MIN_COL_W)
        col_w = (container_w - PAD * 2 - (cols - 1) * PAD) // cols
        card_pad = 8
        thumb_w = col_w - card_pad * 2
        thumb_h = int(thumb_w * 0.75)
        THUMB_DPI = 100

        clr_left = tuple(int(v) for v in (
            (XL_COLOR_LEFT >> 16) & 0xFF, (XL_COLOR_LEFT >> 8) & 0xFF, XL_COLOR_LEFT & 0xFF))
        clr_right = tuple(int(v) for v in (
            (XL_COLOR_RIGHT >> 16) & 0xFF, (XL_COLOR_RIGHT >> 8) & 0xFF, XL_COLOR_RIGHT & 0xFF))

        col = 0
        row = 0
        for pg_idx in page_indices:
            page = doc[pg_idx]
            hits = page_hits.get(pg_idx, set())
            rects_by_token = self._get_multi_word_rects(page, hits)
            if not rects_by_token:
                continue

            nz = THUMB_DPI / 72.0
            pix_n = page.get_pixmap(matrix=fitz.Matrix(nz, nz), alpha=False)
            img_n = Image.frombytes("RGB", [pix_n.width, pix_n.height], pix_n.samples)
            draw = ImageDraw.Draw(img_n, "RGBA")
            for tok, rects in rects_by_token.items():
                status = token_status.get(tok)
                rgb = clr_left if status == "仅左表独有" else clr_right
                for r in rects:
                    draw.rectangle([int(r.x0 * nz), int(r.y0 * nz),
                                    int(r.x1 * nz), int(r.y1 * nz)],
                                   outline=(rgb[0], rgb[1], rgb[2], 255), width=2)
            del draw

            nw, nh = pix_n.width, pix_n.height
            nr = thumb_h / nh if nh > 0 else 1
            img_norm = img_n.resize((max(1, int(nw * nr)), thumb_h), Image.BILINEAR)
            tk_norm = ImageTk.PhotoImage(img_norm)

            card = tk.Frame(thumb_container, bg="white", bd=1, relief=tk.FLAT,
                            highlightbackground=BORDER, highlightthickness=1)
            card.grid(row=row, column=col, padx=PAD // 2, pady=PAD // 2)
            card._tn = tk_norm

            lbl_img = tk.Label(card, image=tk_norm, bg="white", cursor="hand2")
            lbl_img.pack()

            hit_list = sorted(rects_by_token.keys())
            hit_preview = ", ".join(hit_list[:4])
            if len(hit_list) > 4:
                hit_preview += f" 等{len(hit_list)}个"
            lbl_info = tk.Label(card, text=f"第 {pg_idx+1} 页 — {hit_preview}",
                                bg="white", fg="#555", font=("Microsoft YaHei UI", 8),
                                wraplength=thumb_w, pady=2)
            lbl_info.pack()

            def _on_enter(e, c=card):
                c.config(highlightbackground=ACCENT, highlightthickness=2)

            def _on_leave(e, c=card):
                c.config(highlightbackground=BORDER, highlightthickness=1)

            for widget in (card, lbl_img, lbl_info):
                widget.bind("<Enter>", _on_enter)
                widget.bind("<Leave>", _on_leave)

            def make_handler(pg=pg_idx):
                return lambda e: self._jump_from_thumb_xldiff(side, pg, tokens)
            card.bind("<Button-1>", make_handler())
            lbl_img.bind("<Button-1>", make_handler())
            lbl_info.bind("<Button-1>", make_handler())

            col += 1
            if col >= cols:
                col = 0
                row += 1

        thumb_container.update_idletasks()
        scroll_canvas.config(scrollregion=scroll_canvas.bbox("all"))

        def _on_thumb_mousewheel(e):
            scroll_canvas.yview_scroll(int(-1 * (e.delta / 120)), "units")
        scroll_canvas.bind("<MouseWheel>", _on_thumb_mousewheel)
        thumb_container.bind("<MouseWheel>", _on_thumb_mousewheel)

        resize_job = [None]
        def _on_thumb_resize(e):
            new_w = parent.winfo_width()
            if new_w > 100 and abs(new_w - container_w) > 40:
                if resize_job[0]:
                    parent.after_cancel(resize_job[0])
                resize_job[0] = parent.after(300, lambda: self._build_xldiff_thumbnails(
                    parent, side, tokens, page_hits, token_status, page_indices))
        scroll_canvas.bind("<Configure>", _on_thumb_resize)

    def _jump_from_thumb_xldiff(self, side, page_idx, tokens):
        """从Excel差异缩略图跳转回单页视图，定位到指定页并高亮全部选中位号"""
        self._exit_multi_page()
        if side == 1:
            self._cur_page1 = page_idx
        else:
            self._cur_page2 = page_idx
        self._update_cmp_page_label(side)
        self._render_compare_page(side, highlight_words=tokens)
        self._cmp_status.set(f"跳转到{'左' if side==1 else '右'}侧第{page_idx+1}页")

    def _xldiff_clear_highlight(self):
        """清除PDF高亮显示（退出多页视图，恢复为不带高亮的当前页面）。"""
        self._cmp_reset_active_highlight()
        self._exit_multi_page()
        self._cmp_status.set("已清除PDF高亮")

    # ════════════════════════════════════════════════════════════════
    # 多页展开视图
    # ════════════════════════════════════════════════════════════════

    def _show_multi_page(self, word):
        """
        双侧同时进入多页缩略图视图。
        每侧显示所有包含该词页面的缩略图，每页一个子窗口，词高亮。
        """
        self._cmp_multi_btn.pack(side=tk.LEFT, padx=3, pady=6)

        # 左侧
        if self._pdf_doc1:
            pages1 = self._find_word_pages(self._pdf_doc1, word)
            if pages1:
                self._cmp_single1.grid_remove()
                self._cmp_multi1.grid(row=0, column=0, sticky="nsew")
                self._build_thumbnails(self._cmp_multi1, 1, word, pages1)
            else:
                self._cmp_status.set(f"左侧未找到: {word}")

        # 右侧
        if self._pdf_doc2:
            pages2 = self._find_word_pages(self._pdf_doc2, word)
            if pages2:
                self._cmp_single2.grid_remove()
                self._cmp_multi2.grid(row=0, column=0, sticky="nsew")
                self._build_thumbnails(self._cmp_multi2, 2, word, pages2)
            else:
                self._cmp_status.set(f"右侧未找到: {word}")

        self._cmp_status.set(f"多页展开: {word}")

    def _exit_multi_page(self):
        """退出多页缩略图视图，恢复单页画布"""
        # 恢复左侧
        if hasattr(self, '_cmp_multi1'):
            self._cmp_multi1.grid_remove()
            for w in self._cmp_multi1.winfo_children():
                w.destroy()
        if hasattr(self, '_cmp_single1'):
            self._cmp_single1.grid(row=0, column=0, sticky="nsew")

        # 恢复右侧
        if hasattr(self, '_cmp_multi2'):
            self._cmp_multi2.grid_remove()
            for w in self._cmp_multi2.winfo_children():
                w.destroy()
        if hasattr(self, '_cmp_single2'):
            self._cmp_single2.grid(row=0, column=0, sticky="nsew")

        # 隐藏退出按钮
        if hasattr(self, '_cmp_multi_btn'):
            self._cmp_multi_btn.pack_forget()

        self._render_both_pages()

    def _find_word_pages(self, doc, word) -> list:
        """在PDF中搜索包含指定词的页码列表"""
        pages = []
        word_lower = word.lower()
        for pg_idx in range(doc.page_count):
            for w in doc[pg_idx].get_text("words"):
                w_clean = self._clean_word(w[4])
                if w_clean.lower() == word_lower:
                    pages.append(pg_idx)
                    break
        return pages

    def _get_word_rects_on_page(self, page, word) -> list:
        """返回页面上指定词的所有包围矩形（PDF坐标）"""
        rects = []
        word_lower = word.lower()
        for w in page.get_text("words"):
            w_clean = self._clean_word(w[4])
            if w_clean.lower() == word_lower:
                rects.append(fitz.Rect(w[0], w[1], w[2], w[3]))
        return rects

    def _build_thumbnails(self, parent, side, word, page_indices):
        """
        在 parent 容器内构建缩略图网格。
        - 自适应列宽：根据容器宽度计算最优列数和缩略图尺寸
        - 局部裁剪：每个缩略图只显示目标词周围区域，放大展示
        """
        for w in parent.winfo_children():
            w.destroy()

        parent.rowconfigure(0, weight=0)
        parent.rowconfigure(1, weight=1)
        parent.columnconfigure(0, weight=1)

        info_bar = tk.Frame(parent, bg=PANEL, height=32)
        info_bar.grid(row=0, column=0, sticky="ew")
        info_bar.pack_propagate(False)
        tag = "左" if side == 1 else "右"
        tk.Label(info_bar, text=f"{tag}侧 - 包含 '{word}' 的页面 ({len(page_indices)}页)",
                 bg=PANEL, fg=TEXT, font=("Microsoft YaHei UI", 9, "bold"),
                 padx=8).pack(side=tk.LEFT, pady=4)

        scroll_canvas = tk.Canvas(parent, bg="#e8e8e8", highlightthickness=0)
        scrollbar = ttk.Scrollbar(parent, orient=tk.VERTICAL, command=scroll_canvas.yview)
        scroll_canvas.config(yscrollcommand=scrollbar.set)

        thumb_container = tk.Frame(scroll_canvas, bg="white")
        scroll_canvas.create_window((0, 0), window=thumb_container, anchor="nw",
                                     tags="thumb_window")

        scroll_canvas.grid(row=1, column=0, sticky="nsew")
        scrollbar.grid(row=1, column=1, sticky="ns")

        doc = self._pdf_doc1 if side == 1 else self._pdf_doc2
        if not doc:
            return

        # ── 自适应列宽计算 ──
        parent.update_idletasks()
        container_w = parent.winfo_width()
        if container_w < 100:
            container_w = 600  # 默认值

        PAD = 8        # 卡片间距
        MIN_COL_W = 200  # 最小列宽
        cols = max(1, container_w // MIN_COL_W)
        # 每列实际宽度（均分可用空间）
        col_w = (container_w - PAD * 2 - (cols - 1) * PAD) // cols
        # 缩略图目标宽高（减去卡片边框和内边距）
        card_pad = 8
        thumb_w = col_w - card_pad * 2
        thumb_h = int(thumb_w * 0.75)  # 宽高比约4:3

        THUMB_DPI = 100   # 正常缩略图DPI（整页渲染）

        col = 0
        row = 0
        for pg_idx in page_indices:
            page = doc[pg_idx]
            rects = self._get_word_rects_on_page(page, word)
            if not rects:
                continue

            # ── 渲染整页，在页面上精确高亮目标文本 ──
            hl_r, hl_g, hl_b = self._cmp_hl_color

            # 正常版：整页渲染
            nz = THUMB_DPI / 72.0
            pix_n = page.get_pixmap(matrix=fitz.Matrix(nz, nz), alpha=False)
            img_n = Image.frombytes("RGB", [pix_n.width, pix_n.height], pix_n.samples)
            draw = ImageDraw.Draw(img_n, "RGBA")
            for r in rects:
                draw.rectangle([int(r.x0 * nz), int(r.y0 * nz),
                                int(r.x1 * nz), int(r.y1 * nz)],
                               outline=(hl_r, hl_g, hl_b, 255), width=1)
            del draw
            # 缩放填满缩略图
            nw, nh = pix_n.width, pix_n.height
            nr = thumb_h / nh if nh > thumb_h else thumb_h / nh
            img_norm = img_n.resize((int(nw * nr), thumb_h), Image.BILINEAR)

            tk_norm = ImageTk.PhotoImage(img_norm)

            # ── 缩略图卡片 ──
            card = tk.Frame(thumb_container, bg="white", bd=1, relief=tk.FLAT,
                            highlightbackground=BORDER, highlightthickness=1)
            card.grid(row=row, column=col, padx=PAD//2, pady=PAD//2)
            card._tn = tk_norm
            card._pg = pg_idx       # 页码，按需渲染放大版
            card._side = side        # 所属侧
            card._word = word        # 关键词
            card._rects = rects     # 目标词在该页的所有位置 (fitz.Rect列表)
            card._page = page        # fitz Page 对象（供弹窗渲染用）
            card._doc = doc          # fitz Document 对象

            lbl_img = tk.Label(card, image=tk_norm, bg="white", cursor="hand2")
            lbl_img.pack()

            lbl_info = tk.Label(card, text=f"第 {pg_idx+1} 页",
                                bg="white", fg="#555", font=("Microsoft YaHei UI", 8),
                                pady=2)
            lbl_info.pack()

            # ── 悬停：为页面上每个出现位置弹独立窗口 / 离开关闭 ──
            def _on_enter(e, c=card, pg=pg_idx):
                self._hovered_card = c
                self._hovered_page = pg
                c.config(highlightbackground=ACCENT, highlightthickness=2)
                # 取消延迟关闭，显示每个出现位置的独立弹窗
                self._cancel_popup_close()
                self._show_word_occurrence_popups(c)
                if self._ctrl_held:
                    self._show_fullscreen_popup()

            def _on_leave(e, c=card):
                c.config(highlightbackground=BORDER, highlightthickness=1)
                self._hovered_card = None
                # 延迟关闭弹窗（给用户时间移入弹窗），如果用户移入弹窗会取消延迟
                self._schedule_popup_close()
                if not self._ctrl_held:
                    self._hide_fullscreen_popup()

            for widget in (card, lbl_img, lbl_info):
                widget.bind("<Enter>", _on_enter)
                widget.bind("<Leave>", _on_leave)

            # 点击跳转
            def make_handler(pg):
                return lambda e: self._jump_from_thumb(side, pg, word)
            card.bind("<Button-1>", make_handler(pg_idx))
            lbl_img.bind("<Button-1>", make_handler(pg_idx))
            lbl_info.bind("<Button-1>", make_handler(pg_idx))

            col += 1
            if col >= cols:
                col = 0
                row += 1

        # 更新滚动区域
        thumb_container.update_idletasks()
        scroll_canvas.config(scrollregion=scroll_canvas.bbox("all"))

        # 滚轮支持
        def _on_thumb_mousewheel(e):
            scroll_canvas.yview_scroll(int(-1 * (e.delta / 120)), "units")
        scroll_canvas.bind("<MouseWheel>", _on_thumb_mousewheel)
        thumb_container.bind("<MouseWheel>", _on_thumb_mousewheel)

        # 容器宽度变化时防抖重新布局
        resize_job = [None]  # mutable container for the after id
        def _on_thumb_resize(e):
            new_w = parent.winfo_width()
            if new_w > 100 and abs(new_w - container_w) > 40:
                if resize_job[0]:
                    parent.after_cancel(resize_job[0])
                resize_job[0] = parent.after(300, lambda: self._build_thumbnails(
                    parent, side, word, page_indices))
        scroll_canvas.bind("<Configure>", _on_thumb_resize)

    # ════════════════════════════════════════════════════════════════
    # 全屏弹窗放大（Ctrl+悬停）
    # ════════════════════════════════════════════════════════════════

    def _on_ctrl_down(self):
        """Ctrl按下：记录状态，如果鼠标在某卡片上则弹全屏"""
        self._ctrl_held = True
        if self._hovered_card:
            self._show_fullscreen_popup()

    def _on_ctrl_up(self):
        """Ctrl松开：关闭全屏"""
        self._ctrl_held = False
        self._hide_fullscreen_popup()

    def _on_shift_down(self):
        """Shift按下：切换放大锁定（按一次锁住，再按一次关闭）"""
        self._shift_held = not self._shift_held
        if self._shift_held:
            # 锁定：如果已有悬停卡片则立即显示
            if self._hz_card and self._hz_img:
                self._show_card_zoom(self._hz_card, self._hz_img, self._hz_idx,
                                     self._hz_page, self._hz_rect, self._hz_pad)
        else:
            # 解锁：关闭放大
            self._hide_card_zoom()

    def _on_shift_up(self):
        """Shift松开：无操作（Toggle 模式不需要一直按着）"""
        pass

    def _show_fullscreen_popup(self):
        """弹出全屏窗口显示高清放大视图"""
        if self._fs_popup:
            return
        card = self._hovered_card
        if not card or not hasattr(card, '_pg'):
            return

        # ── 按需渲染高DPI放大图 ──
        side = card._side
        pg_idx = card._pg
        word = card._word
        doc = self._pdf_doc1 if side == 1 else self._pdf_doc2
        if not doc:
            return
        page = doc[pg_idx]
        rects = self._get_word_rects_on_page(page, word)

        FS_DPI = 250
        zz = FS_DPI / 72.0
        pix = page.get_pixmap(matrix=fitz.Matrix(zz, zz), alpha=False)
        pil_img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
        hl_r, hl_g, hl_b = self._cmp_hl_color
        draw = ImageDraw.Draw(pil_img, "RGBA")
        for r in rects:
            draw.rectangle([int(r.x0 * zz), int(r.y0 * zz),
                            int(r.x1 * zz), int(r.y1 * zz)],
                           outline=(hl_r, hl_g, hl_b, 255), width=2)
        del draw

        # ── 创建弹窗 ──
        popup = tk.Toplevel(self)
        popup.configure(bg=POPUP_BG)
        sw = self.winfo_screenwidth()
        sh = self.winfo_screenheight()
        popup.geometry(f"{sw}x{sh}+0+0")
        popup.overrideredirect(True)
        popup.attributes("-topmost", True)

        popup.bind("<Escape>", lambda e: self._on_ctrl_up_and_close())

        # ── 先建 Canvas ──
        canvas = tk.Canvas(popup, bg=POPUP_BG, highlightthickness=0)
        canvas.pack(fill=tk.BOTH, expand=True)
        popup._fs_canvas = canvas

        # ── 鼠标拖拽平移 / 单击关闭 ──
        def _on_press(e):
            canvas.scan_mark(e.x, e.y)
            popup._drag_start = (e.x, e.y)

        def _on_drag(e):
            canvas.scan_dragto(e.x, e.y, gain=1)

        def _on_release(e):
            sx, sy = getattr(popup, '_drag_start', (e.x, e.y))
            if abs(e.x - sx) < 5 and abs(e.y - sy) < 5:
                self._on_ctrl_up_and_close()
            popup._drag_start = None

        canvas.bind("<ButtonPress-1>", _on_press)
        canvas.bind("<B1-Motion>", _on_drag)
        canvas.bind("<ButtonRelease-1>", _on_release)

        popup._fs_factor = 1.0
        popup._fs_pil = pil_img
        popup._fs_rects = rects
        popup._fs_page = page
        popup._fs_word_zz = zz
        pil_w, pil_h = pil_img.size
        wr = (sw - 40) / pil_w
        hr = (sh - 80) / pil_h
        popup._fs_scale = min(wr, hr)

        def render_fs():
            fw = int(pil_w * popup._fs_scale * popup._fs_factor)
            fh = int(pil_h * popup._fs_scale * popup._fs_factor)
            img = pil_img.resize((fw, fh), Image.LANCZOS)
            popup._fs_tk = ImageTk.PhotoImage(img)
            canvas.delete("all")
            canvas.create_image(sw//2, sh//2, anchor="center", image=popup._fs_tk)
            canvas.config(scrollregion=canvas.bbox("all"))

        render_fs()

        def _fs_wheel(e):
            delta = 1.15 if e.delta > 0 else 1 / 1.15
            popup._fs_factor = max(0.2, min(popup._fs_factor * delta, 10.0))
            render_fs()
        canvas.bind("<Control-MouseWheel>", _fs_wheel)
        popup.bind("<Control-MouseWheel>", _fs_wheel)

        self._fs_popup = popup

    def _on_ctrl_up_and_close(self):
        """松开Ctrl并关闭弹窗（用于Esc/点击关闭）"""
        self._ctrl_held = False
        self._hide_fullscreen_popup()

    def _hide_fullscreen_popup(self):
        self._ctrl_held = False
        if self._fs_popup:
            try:
                self._fs_popup.destroy()
            except Exception:
                pass
            self._fs_popup = None

    # ════════════════════════════════════════════════════════════════
    # 悬停弹窗 — 单个滚动窗口内网格展示所有出现位置
    # ════════════════════════════════════════════════════════════════

    def _show_word_occurrence_popups(self, card):
        """
        鼠标悬停缩略图时，为页面上每个目标词出现位置渲染裁剪视图，
        统一收纳到一个带滚动条的窗口内网格排列。
        支持开关控制 + 可调显示范围 + 定位到主窗口所在屏幕。
        """
        if not self._popup_enabled:
            return
        if not card or not hasattr(card, '_rects'):
            return

        rects = card._rects
        if not rects:
            return

        self._hide_word_occurrence_popups()

        page = card._page
        word = card._word
        pg_idx = card._pg
        hl_r, hl_g, hl_b = self._cmp_hl_color
        pad = self._popup_pad

        # ── 步骤1：整页一次渲染（250 DPI），内存裁剪所有出现位置 ──
        rendered = []  # [(pil_img, fitz_rect), ...]
        zz = 250 / 72.0  # 卡片渲染 DPI（一次整页，N 倍提速）
        try:
            full_pix = page.get_pixmap(matrix=fitz.Matrix(zz, zz), alpha=False)
            full_img = Image.frombytes("RGB", [full_pix.width, full_pix.height], full_pix.samples)
        except Exception:
            return

        for rect in rects:
            # 图像像素坐标的裁剪矩形
            x0 = max(0, int((rect.x0 - pad) * zz))
            y0 = max(0, int((rect.y0 - pad) * zz))
            x1 = min(full_img.width, int((rect.x1 + pad) * zz))
            y1 = min(full_img.height, int((rect.y1 + pad) * zz))
            if x0 >= x1 or y0 >= y1:
                continue
            img = full_img.crop((x0, y0, x1, y1))
            # 高亮目标词（裁剪图内的相对坐标）
            draw = ImageDraw.Draw(img, "RGBA")
            draw.rectangle([
                int((rect.x0 * zz) - x0), int((rect.y0 * zz) - y0),
                int((rect.x1 * zz) - x0), int((rect.y1 * zz) - y0)
            ], outline=(hl_r, hl_g, hl_b, 255), width=3)
            del draw
            rendered.append((img, rect))

        if not rendered:
            return

        count = len(rendered)

        # ── 步骤2：计算窗口尺寸 & 卡片网格参数 ──
        # 定位到主窗口所在屏幕
        main_x = self.winfo_rootx()
        main_y = self.winfo_rooty()
        main_w = self.winfo_width()
        main_h = self.winfo_height()

        # 窗口大小：根据数量自适应，有上限
        if count <= 4:
            want_cols = count
        elif count <= 8:
            want_cols = 4
        else:
            want_cols = 5

        card_img_w = 320   # 卡片内图片目标宽度
        card_img_h = 240   # 卡片内图片目标高度
        card_pad = 6       # 卡片内边距
        gap = 8            # 卡片间距
        title_h = 30       # 标题栏高度
        card_w = card_img_w + card_pad * 2
        card_h = card_img_h + card_pad * 2 + 20  # +20 for label

        popup_w = min(1050, card_w * want_cols + gap * (want_cols - 1) + 30)
        popup_h = min(750, main_h - 80)

        # 实际列数（根据弹窗宽度重新算）
        cols = max(1, (popup_w - 30) // (card_w + gap))
        rows = (count + cols - 1) // cols
        total_content_w = cols * card_w + (cols - 1) * gap
        total_content_h = rows * card_h + (rows - 1) * gap

        # ── 步骤3：创建主弹窗 ──
        popup = tk.Toplevel(self)
        popup.title(f"第{pg_idx+1}页 · {word} — {count}处出现")
        popup.configure(bg=POPUP_BG)
        popup.attributes("-topmost", True)

        # 定位：主窗口外置 4 方向候选（绝不与主窗口重叠，杜绝闪烁）
        screen_w = popup.winfo_screenwidth()
        screen_h = popup.winfo_screenheight()
        gap = 10
        # 候选：右 → 左 → 下 → 上
        candidates = [
            (main_x + main_w + gap, main_y),                                # 右侧
            (main_x - popup_w - gap, main_y),                               # 左侧
            (main_x + (main_w - popup_w) // 2, main_y + main_h + gap),      # 下方
            (main_x + (main_w - popup_w) // 2, main_y - popup_h - gap),     # 上方
        ]
        px, py = candidates[0]
        for cx, cy in candidates:
            if 0 <= cx and 0 <= cy and cx + popup_w <= screen_w and cy + popup_h <= screen_h:
                px, py = cx, cy
                break
        # clamp 备选
        px = max(0, min(px, screen_w - popup_w))
        py = max(0, min(py, screen_h - popup_h))
        popup.geometry(f"{popup_w}x{popup_h}+{px}+{py}")
        popup.minsize(400, 300)

        # 关闭协议
        popup.protocol("WM_DELETE_WINDOW", self._hide_word_occurrence_popups)
        popup.bind("<Escape>", lambda e: self._hide_word_occurrence_popups())

        # ── 悬停交互：进入弹窗→保持；离开→延迟关闭 ──
        popup.bind("<Enter>", lambda e: self._cancel_popup_close())
        popup.bind("<Leave>", lambda e: self._schedule_popup_close())

        # ── 步骤4：构建滚动画布 + 内部网格 ──
        canvas = tk.Canvas(popup, bg=POPUP_BG, highlightthickness=0)
        scrollbar = ttk.Scrollbar(popup, orient=tk.VERTICAL, command=canvas.yview)
        canvas.config(yscrollcommand=scrollbar.set)

        inner = tk.Frame(canvas, bg=POPUP_BG, padx=10, pady=10)
        canvas.create_window((0, 0), window=inner, anchor="nw", tags="inner")

        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        # 滚轮支持
        def _on_canvas_wheel(e):
            canvas.yview_scroll(int(-1 * (e.delta / 120)), "units")
        canvas.bind("<MouseWheel>", _on_canvas_wheel)
        inner.bind("<MouseWheel>", _on_canvas_wheel)

        # ── 步骤5：逐张填入卡片 ──
        for i, (img, rect) in enumerate(rendered):
            row = i // cols
            col = i % cols

            # 创建卡片
            card_frame = tk.Frame(inner, bg=POPUP_CARD, bd=0,
                                  highlightbackground="#444", highlightthickness=1)
            card_frame.grid(row=row, column=col, padx=gap // 2, pady=gap // 2,
                            sticky="nsew")
            # 存储 zoom 所需上下文
            card_frame._zoom_page = page
            card_frame._zoom_rect = rect
            card_frame._zoom_pad = pad
            card_frame._zoom_img = img   # 250DPI 原图

            # 缩放图片填满卡片
            scale = min(card_img_w / img.width, card_img_h / img.height)
            iw, ih = int(img.width * scale), int(img.height * scale)
            try:
                thumb = img.resize((iw, ih), Image.LANCZOS)
                tk_img = ImageTk.PhotoImage(thumb)
            except Exception:
                continue
            card_frame._tk = tk_img   # 防 GC

            img_lbl = tk.Label(card_frame, image=tk_img, bg=POPUP_CARD,
                               cursor="hand2")
            img_lbl.pack(padx=card_pad, pady=(card_pad, 0))

            # 序号标签
            lbl = tk.Label(card_frame, text=f"#{i+1}/{count}  [{rect.x0:.0f},{rect.y0:.0f}]",
                           bg=POPUP_CARD, fg=POPUP_DIM,
                           font=("Microsoft YaHei UI", 8))
            lbl.pack(pady=(2, card_pad))

            # 卡片悬停：高亮边框 + 追踪变量 + Shift锁定时自动更新放大
            def _card_enter(e, cf=card_frame, idx=i, pil_img=img, pg=page, r=rect, p=pad):
                cf.config(highlightbackground=ACCENT, highlightthickness=2)
                self._cancel_popup_close()
                # 追踪当前悬停的卡片
                self._hz_card = cf
                self._hz_img = pil_img
                self._hz_page = pg
                self._hz_rect = r
                self._hz_idx = idx
                self._hz_pad = p
                # Shift 已锁定 → 自动更新放大到新卡片
                if self._shift_held:
                    self._show_card_zoom(cf, pil_img, idx, pg, r, p)
            def _card_leave(e, cf=card_frame):
                cf.config(highlightbackground="#444", highlightthickness=1)
                self._schedule_popup_close()
                self._hz_card = None
                self._hz_img = None
                self._hz_page = None
                self._hz_rect = None
            for w in (card_frame, img_lbl, lbl):
                w.bind("<Enter>", _card_enter)
                w.bind("<Leave>", _card_leave)
                w.bind("<Enter>", lambda e: self._cancel_popup_close(), add="+")
                w.bind("<Leave>", lambda e: self._schedule_popup_close(), add="+")

            # 点击卡片：退出多页+弹窗，跳转到对应页面
            def _make_click_handler(side, pg, r):
                return lambda e: self._jump_to_rect(side, pg, r)
            card_frame.bind("<Button-1>", _make_click_handler(card._side, pg_idx, rect))
            img_lbl.bind("<Button-1>", _make_click_handler(card._side, pg_idx, rect))

        # 更新滚动区域
        inner.update_idletasks()
        canvas.config(scrollregion=canvas.bbox("all"))
        popup._inner = inner

        self._word_popups = [popup]

        # Ctrl 按下同时显示全屏弹窗
        if self._ctrl_held:
            self._show_fullscreen_popup()

    def _jump_to_rect(self, side, pg_idx, rect):
        """点击弹窗卡片 → 退出多页视图 + 弹窗，跳转到对应页"""
        self._exit_multi_page()
        self._hide_word_occurrence_popups()
        if side == 1:
            self._cur_page1 = pg_idx
        else:
            self._cur_page2 = pg_idx
        self._update_cmp_page_label(side)
        self._render_compare_page(side)
        self._cmp_status.set(f"跳转到{'左' if side==1 else '右'}侧第{pg_idx+1}页")

    def _hide_word_occurrence_popups(self):
        """关闭弹窗"""
        self._hide_card_zoom()   # 同步收起卡片放大窗口
        self._hz_card = None     # 清追踪
        self._hz_img = None
        self._hz_page = None
        self._hz_rect = None
        for p in self._word_popups:
            try:
                p.destroy()
            except Exception:
                pass
        self._word_popups = []
        self._cancel_popup_close()

    # ── 卡片悬停放大 ──

    def _show_card_zoom(self, card_frame, pil_img, idx,
                         page=None, rect=None, pad=None):
        """显示可跨主窗口拖动、可缩放并记住位置的高清视图。"""
        if self._card_zoom_popup:
            try:
                self._card_zoom_geometry = self._card_zoom_popup.geometry()
                self._card_zoom_popup.destroy()
            except Exception:
                pass
            self._card_zoom_popup = None

        # ── 如果有 page+rect，用 400DPI 重渲染（比卡片图更清晰）──
        if page is not None and rect is not None:
            zz_hi = 400 / 72.0
            p = pad if pad is not None else self._popup_pad
            bbox = fitz.Rect(rect)
            bbox.x0 = max(0, bbox.x0 - p)
            bbox.y0 = max(0, bbox.y0 - p)
            bbox.x1 = min(page.rect.width, bbox.x1 + p)
            bbox.y1 = min(page.rect.height, bbox.y1 + p)
            try:
                pix = page.get_pixmap(matrix=fitz.Matrix(zz_hi, zz_hi),
                                      clip=bbox, alpha=False)
                pil_img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
                # 高亮
                draw = ImageDraw.Draw(pil_img, "RGBA")
                hl_r, hl_g, hl_b = self._cmp_hl_color
                draw.rectangle([
                    int((rect.x0 - bbox.x0) * zz_hi), int((rect.y0 - bbox.y0) * zz_hi),
                    int((rect.x1 - bbox.x0) * zz_hi), int((rect.y1 - bbox.y0) * zz_hi)
                ], outline=(hl_r, hl_g, hl_b, 255), width=3)
                del draw
            except Exception:
                pass

        # ── 渲染放大图像 ──
        ZOOM_W, ZOOM_H = 640, 480
        scale = min(ZOOM_W / pil_img.width, ZOOM_H / pil_img.height, 2.5)
        if scale < 0.8:
            scale = 0.8
        ziw = int(pil_img.width * scale)
        zih = int(pil_img.height * scale)
        try:
            zoom_img = pil_img.resize((ziw, zih), Image.LANCZOS)
            tk_zoom = ImageTk.PhotoImage(zoom_img)
            zoom_img.close()
        except Exception:
            return

        # ── 创建浮动放大窗口 ──
        popup = tk.Toplevel(self)
        popup.attributes("-topmost", True)
        popup.configure(bg=POPUP_BG)
        popup.title(f"PDF 高清放大 #{idx + 1}")
        popup.minsize(420, 320)
        popup.resizable(True, True)

        # 边框
        border = tk.Frame(popup, bg=ACCENT, bd=0)
        border.pack(fill=tk.BOTH, expand=True, padx=2, pady=2)

        canvas = tk.Canvas(border, width=ziw, height=zih,
                           bg=POPUP_BG, highlightthickness=0,
                           cursor="arrow")
        canvas.pack(fill=tk.BOTH, expand=True)
        image_id = canvas.create_image(
            ziw // 2, zih // 2, anchor="center", image=tk_zoom)
        popup._tk = tk_zoom   # 防 GC

        # 序号标签（半透明效果 → 暗底白字）
        index_id = canvas.create_text(
            ziw - 8, zih - 8, anchor="se", text=f"#{idx+1}",
            fill="#cccccc", font=("Microsoft YaHei UI", 10, "bold"))

        def recenter(event):
            canvas.coords(image_id, event.width // 2, event.height // 2)
            canvas.coords(index_id, event.width - 8, event.height - 8)

        canvas.bind("<Configure>", recenter)

        # ── 鼠标位置反向定位：放大窗口绝不遮盖鼠标，杜绝 Leave 闪烁 ──
        screen_w = popup.winfo_screenwidth()
        screen_h = popup.winfo_screenheight()
        mx = popup.winfo_pointerx()
        my = popup.winfo_pointery()
        gap = 24

        # 鼠标在左半屏 → zoom 放右边；右半屏 → 放左边
        if mx < screen_w / 2:
            px = mx + gap
        else:
            px = mx - ziw - gap - 6
        # 鼠标在上半屏 → zoom 放下边；下半屏 → 放上边
        if my < screen_h / 2:
            py = my + gap
        else:
            py = my - zih - gap - 6

        # Clamp 到屏幕内
        px = max(0, min(px, screen_w - ziw - 6))
        py = max(0, min(py, screen_h - zih - 6))
        if self._card_zoom_geometry:
            popup.geometry(self._card_zoom_geometry)
        else:
            popup.geometry(f"{ziw + 4}x{zih + 4}+{px}+{py}")
        popup.bind("<Enter>", lambda event: self._cancel_popup_close())
        canvas.bind("<Enter>", lambda event: self._cancel_popup_close())
        popup.protocol("WM_DELETE_WINDOW", self._hide_card_zoom)

        self._card_zoom_popup = popup

    def _hide_card_zoom(self):
        """关闭卡片放大窗口"""
        self._shift_held = False   # 解开锁定
        if self._card_zoom_popup:
            try:
                self._card_zoom_geometry = self._card_zoom_popup.geometry()
                self._card_zoom_popup.destroy()
            except Exception:
                pass
            self._card_zoom_popup = None

    def _schedule_popup_close(self):
        """延迟 300ms 后关闭弹窗（给用户时间移入弹窗）"""
        if self._word_popup_close_id:
            self.after_cancel(self._word_popup_close_id)
        self._word_popup_close_id = self.after(300, self._hide_word_occurrence_popups)

    def _cancel_popup_close(self):
        """取消延迟关闭"""
        if self._word_popup_close_id:
            self.after_cancel(self._word_popup_close_id)
            self._word_popup_close_id = None

    def _jump_from_thumb(self, side, page_idx, word):
        """从缩略图跳转回单页视图，定位到指定页并高亮词"""
        self._exit_multi_page()
        if side == 1:
            self._cur_page1 = page_idx
        else:
            self._cur_page2 = page_idx
        self._update_cmp_page_label(side)
        self._render_compare_page(side, highlight_words={word})
        self._cmp_status.set(f"跳转到{'左' if side==1 else '右'}侧第{page_idx+1}页: {word}")

