        hdr.grid(row=0, column=0, sticky="ew")
        hdr.pack_propagate(False)
        tk.Label(hdr, text="🔧 脚本工坊 — PowerShell 脚本集中管理",
                 bg=PANEL, fg=TEXT, font=("Microsoft YaHei UI", 12, "bold"),
                 padx=12).pack(side=tk.LEFT, pady=6)
